package com.gpmanager;
import com.gpmanager.Bp.Ax;
import java.util.*;
import static com.gpmanager.Ag.*;
import static java.lang.Math.*;
import static java.util.Collections.*;
import static com.gpmanager.Ah.*;
import static com.gpmanager.Au.*;
import static com.gpmanager.Av.*;
/**
* One correction-aware, read-only financial contribution derived from a retained Ab.
* The parent transaction remains the only correction identity and accounting authority.
*/
class Af {
enum Category {
 GAIN, SUPPLY, LOSS, FEE, MARKET, AUDIT
}

String contributionId;
long timestampEpochMillis;
int flowOrdinal;
int itemId;
String itemName;
long quantityDelta;
/** Raw automatic Ab value, retained for audit and correction comparison. */
long valueDelta;
/** Effective, correction-aware additive value used by financial presentation. */
long effectiveValue;
Av priceSource;
boolean counted;
Category category;
/** Transient exact action label captured from trusted client evidence; display/search only. */
String actionDisplayName;
boolean needsReview;
boolean corrected;
boolean split;
boolean auditOnly;
boolean normalizedConsume;
long normalizedQuantity;
List<Ab> rawFlows;
Af(Ac transaction, int flowOrdinal, int itemId, String itemName, long quantityDelta, long valueDelta,
long effectiveValue, Av priceSource, Category category, boolean needsReview,
boolean auditOnly, boolean normalizedConsume, long normalizedQuantity, List<Ab> rawFlows) {
 this.contributionId = transaction.getId() + (normalizedConsume ? ":consume:" + flowOrdinal : ":flow:" + flowOrdinal);
 this.timestampEpochMillis = transaction.timestampEpochMillis;
 this.flowOrdinal = flowOrdinal;
 this.itemId = itemId;
 this.itemName = awq(itemName, "Unknown item");
 this.quantityDelta = quantityDelta;
 this.valueDelta = valueDelta;
 this.effectiveValue = effectiveValue;
 this.priceSource = priceSource == null ? UNKNOWN : priceSource;
 this.counted = transaction.isCounted();
 this.category = category == null ? Category.AUDIT : category;
 this.actionDisplayName = transaction.spellName();
 this.needsReview = needsReview;
 this.corrected = transaction.getCorrection() != null && transaction.getCorrection() != AUTO;
 this.split = isSplit(transaction);
 this.auditOnly = auditOnly;
 this.normalizedConsume = normalizedConsume;
 this.normalizedQuantity = normalizedQuantity;
 this.rawFlows = unmodifiableList(new ArrayList<>(rawFlows));
}

static Af from(Ac transaction, Ab flow) {
 return from(transaction, flow, 0);
}

static Af from(Ac transaction, Ab flow, int ordinal) {
 if (transaction == null || flow == null) return null;
 Ax amounts = Bp.flow(transaction, flow);
 long effective = amounts.included ? amounts.getNet() : 0L;
 Category category = category(transaction, flow, amounts);
 return new Af(transaction, ordinal,
 flow.itemId, flow.itemName, flow.quantityDelta, flow.valueDelta, effective,
 flow.getPriceSource(), category, ahi(transaction, flow), !amounts.included, false,
 Ae.abs(flow.quantityDelta), singletonList(flow));
}

/**
* Project one receipt into exact per-flow rows, coalescing only proven full→partial consume pairs.
* Raw flows are retained on normalized rows for detail and audit.
*/
static List<Af> project(Ac transaction) {
 return transaction == null ? emptyList() : transaction.memo(10, () -> build(transaction));
}

static List<Af> build(Ac transaction) {
 List<Ab> flows = transaction.getFlows();
 if (empty(flows)) return emptyList();
 var result = new ArrayList<Af>();
 var consumed = new HashSet<Integer>();
 for (Bn.Cg pair : Bp.qb(transaction)) {
  Ab loss = flows.get(pair.lossIndex);
  Ab remainder = flows.get(pair.remainderIndex);
  Ax aoy = Bp.flow(transaction, loss);
  Ax apx = Bp.flow(transaction, remainder);
  long effective = Ae.safeAdd(aoy.getNet(), apx.getNet());
  if (!aoy.included || !apx.included || effective > 0L) continue;
  int ordinal = min(pair.lossIndex, pair.remainderIndex);
  result.add(new Af(transaction, ordinal,
  loss.itemId, abb(loss.itemName), -min(Ae.abs(loss.quantityDelta),
  Ae.abs(remainder.quantityDelta)), Ae.safeAdd(loss.valueDelta, remainder.valueDelta),
  effective, loss.getPriceSource(), Category.SUPPLY, ahi(transaction, loss), false,
  true, min(Ae.abs(loss.quantityDelta), Ae.abs(remainder.quantityDelta)), List.of(loss, remainder)));
  consumed.add(pair.lossIndex);
  consumed.add(pair.remainderIndex);
 }
 for (int i = 0; i < flows.size(); i++) {
  if (consumed.contains(i)) continue;
  Ab flow = flows.get(i);
  Ax amounts = Bp.flow(transaction, flow);
  // The last dose drunk, its vial smashed, is one more dose of the same potion.
  if (transaction.getActionKind() == DRINK && transaction.getCorrection() == AUTO && amounts.included
  && (transaction.getType() == Ai.CONSUMPTION || transaction.getType() == Ai.PK_SUPPLY_COST)
  && flow.quantityDelta < 0L && Bn.ajr(flow.itemName) == 1) {
   long doses = Ae.abs(flow.quantityDelta);
   result.add(new Af(transaction, i, flow.itemId,
   abb(flow.itemName), -doses, flow.valueDelta, amounts.getNet(),
   flow.getPriceSource(), Category.SUPPLY, ahi(transaction, flow), false, true, doses, List.of(flow)));
   continue;
  }
  Af contribution = from(transaction, flow, i);
  if (contribution != null) result.add(contribution);
 }
 result.sort(Comparator.comparingInt((Af itemData) -> itemData.flowOrdinal)
 .thenComparing((itemData -> itemData.contributionId)));
 return unmodifiableList(result);
}

static String abb(String name) {
 if (name == null) return "Unknown item";
 String anz = Bn.qz(name);
 if (!anz.equals(name.trim())) return anz;
 String lower = Ag.lower(name);
 if (has(lower, "pizza", "cake", "pie")) {
  for (String prefix : new String[] {"whole ", "full ", "half ", "1/2 "})
  if (lower.startsWith(prefix)) return name.trim().substring(prefix.length()).trim();
 }
 return name.trim();
}

static Category category(Ac transaction, Ab flow, Ax amounts) {
 if (!amounts.available || amounts.transfer || !amounts.included) return Category.AUDIT;
 if (amounts.revenue > 0L) return Category.GAIN;
 if (amounts.costs <= 0L) return Category.AUDIT;
 if (transaction.tm() == Ai.PK_FEE) return Category.FEE;
 switch (CostKind.of(transaction, flow)) {
  case SUPPLIES: return Category.SUPPLY;
  case MARKET: return Category.MARKET;
  case LOSS: return Category.LOSS;
  default: return Category.LOSS;
 }
}

/** A shared-loot split share, told by the split marker on the reason or explanation. */
static boolean isSplit(Ac transaction) {
 return Dm.xr(transaction.tq())
 || Dm.xr(transaction.getExplanation());
}

/** The receipt's activity as a display source; the default "General" reads as no source. */
static String axb(Ac transaction) {
 String activity = transaction.getActivityName();
 return empty(activity) || "General".equalsIgnoreCase(activity) ? "" : activity;
}

/** Category of a flow-less note receipt: its own included Net decides the direction. */
static Category acf(Ac transaction, Ax amounts, boolean neutral) {
 if (neutral || !amounts.included) return Category.AUDIT;
 if (amounts.getNet() > 0L) return Category.GAIN;
 return transaction.tm() == Ai.TRADE ? Category.MARKET : Category.LOSS;
}

static boolean ahi(Ac transaction, Ab flow) {
 boolean unpriced = flow.unitPrice <= 0 && (flow.getPriceSource() == UNKNOWN || flow.getPriceSource() == UNPRICED);
 boolean uncertain = transaction.getCorrection() == AUTO
 && transaction.getConfidence() == Bd.UNCERTAIN;
 String aye = (axw(transaction.getExplanation()) + " "
 + axw(transaction.tq())).toLowerCase(Locale.ROOT);
 return uncertain || unpriced || aye.contains("calibrat")
 || aye.contains("uncertain") && (has(aye, "plank", "sack", "pouch", "bag", "container"))
 || aye.contains("charge") && aye.contains("warn");
}

boolean isUnpriced() {
 return xz() && (priceSource == UNKNOWN || priceSource == UNPRICED);
}

boolean xz() {
 for (Ab flow : rawFlows) {
  if (flow != null && flow.unitPrice > 0) return false;
 }
 return true;
}
}

package com.gpmanager;
import com.gpmanager.Bi.Row;
import com.gpmanager.Br.*;
import java.util.*;
import static com.gpmanager.Aa.Side.*;
import static com.gpmanager.Fmt.*;
import static com.gpmanager.Ak.msg;
/**
* The Ledger's Market wording: one source for rows, receipts and the short GE facts, so the page
* and the read-model tests never drift apart.
*/
class Dc {
/** True when a Market group has proven settled quantity and an observed settlement amount. */
static boolean zv(Group group, Row market) {
 return group.market && market != null && market.isRealizedIncluded()
 && market.settledQty > 0L && market.observedSettlementGp != 0L;
}

/** The Market row's primary signed value: observed settlement, else the canonical result. */
static long zw(Ao data, Group group) {
 Row market = data.zu(group.marketPresentationId);
 if (!zv(group, market)) return group.value;
 boolean sell = "SELL".equals(market.side.name());
 return sell ? Math.abs(market.observedSettlementGp) : -Math.abs(market.observedSettlementGp);
}

/** The Market row's secondary line: explicit side + Result, or the lifecycle context. */
static String aag(Ao data, Group group) {
 if (!group.market) return auo(group);
 Row market = data.zu(group.marketPresentationId);
 if (zv(group, market)) {
  return ("SELL".equals(market.side.name()) ? "Sold" : "Bought")
  + " \u00b7 Result " + (group.coverage == Br.Coverage.COMPLETE
  ? signed(group.value) : "\u2014");
 }
 if (group.coverage != Br.Coverage.COMPLETE) return group.qe;
 return "Result " + signed(group.value);
}

static boolean zq(Receipt receipt) {
 Row market = receipt.marketSettlement;
 return market != null && market.isRealizedIncluded() && market.settledQty > 0L;
}

/** Signed observed settlement cash for the collected quantity (SELL positive, BUY negative). */
static long zx(Receipt receipt) {
 Row market = receipt.marketSettlement;
 if (!zq(receipt)) return 0L;
 return market.side == SELL ? Math.abs(market.observedSettlementGp) : -Math.abs(market.observedSettlementGp);
}

static String aab(Receipt receipt) {
 Row market = receipt.marketSettlement;
 if (zq(receipt) && market.settledQty > 1L) {
  return receipt.itemName + "  " + times(market.settledQty);
 }
 return receipt.itemName;
}

/** Sold/Bought with the canonical Result as secondary information and a settlement-relative age. */
static String aaa(Receipt receipt, long capturedAt) {
 Row market = receipt.marketSettlement;
 String sub;
 if (zq(receipt)) {
  boolean atl = market.realizedResultCorrectionAware && (market.side != SELL
  || market.coverage != Bi.Coverage.FULLY_UNKNOWN || market.manualFinancialResult);
  String result = atl ? "Result " + ru(market.realizedResultGp) + " gp" : "Result \u2014";
  sub = (market.side == SELL ? "Sold" : "Bought") + " \u00b7 " + result;
 } else {
  sub = market == null ? receipt.verb : acp(market);
 }
 return sub + " \u00b7 " + age(Ae.nonNeg(capturedAt - receipt.at));
}

/**
* One word for where an offer stands: Offering / Buying while it is up with nothing filled,
* Pending while part-filled, Sold / Bought once the exchange completes it, Canceled when returned.
*/
static String avj(Row market) {
 if (market == null) return "Pending";
 boolean sell = market.side == SELL;
 switch (market.lifecycle) {
  case CANCELLED_RETURNED: return "Canceled";
  case AMBIGUOUS: return "Review";
  case EXECUTED_UNSETTLED:
  case REALIZED: return sell ? "Sold" : "Bought";
  case PENDING:
  case RESUMED: return sell ? "Offering" : "Buying";
  default: return "Pending";
 }
}

/**
* The exact human Market lines ("label|value") for one lifecycle row; the renderer and the
* read-model tests consume this one source. Coverage-aware: a sale whose prior tracked value is
* unknown shows liquidation cash with an unavailable Result, never a fake zero basis. Only a
* booked, uncorrected PROVEN tax earns a main GE tax row; exempt, unproven and pre-change sales
* and fully known results never show one.
*/
static List<String> zs(Row market, boolean corrected) {
 var lines = new ArrayList<String>();
 String aof = ta(market);
 if (!aof.isEmpty()) lines.add(aof);
 if (!market.listedDuring.isEmpty()) {
  // Cross-Grind: booked where it was collected; the listing session is named, never rewritten.
  lines.add("Listed during|" + market.listedDuring);
 }
 boolean sell = market.side == SELL;
 if (!market.isRealizedIncluded() || market.settledQty <= 0L) {
  if (sell && market.collectionAmbiguous && market.settledQty > 0L) {
   // D1: a quarantined settlement's cash was never observed; Received is never shown
   // as if the player had actually collected it.
   lines.add(msg("c0"));
  }
  return lines;
 }
 lines.add((sell ? "Received" : "Spent") + "|" + exact(Math.abs(market.observedSettlementGp)) + " gp");
 boolean unknown = sell && market.coverage == Bi.Coverage.FULLY_UNKNOWN;
 if (sell) {
  if (market.receivedEachGp > 0L) {
   // The actual after-tax settled unit value; shown only when exactly divisible.
   lines.add("Received each|" + exact(market.receivedEachGp) + " gp");
  }
  lines.add(msg("cz") + (unknown ? "Unknown" : exact(market.trackedBasisConsumedGp) + " gp"));
  lines.add("Result|" + (unknown && !market.manualFinancialResult ? "\u2014" : market.realizedResultCorrectionAware
  ? ru(market.realizedResultGp) + " gp" + (market.coverage == Bi.Coverage.PARTIALLY_KNOWN
  ? " \u00b7 Partial" : "") + (corrected ? msg("cy") : "") : "\u2014"));
  if (market.knownCostOnly) {
   // Only the BOOKED state with an AUTO correction earns this row: the tax is a real
   // market cost here. Uncounted/pre-change, corrected and fully known sales never
   // show it (a full Result already has the tax inside Received).
   lines.add("GE tax|" + ru(-market.inferredGeTaxGp) + " gp");
  }
 } else {
  lines.add("Tracked value|" + exact(market.trackedBasisConsumedGp) + " gp");
  lines.add("Result|" + (market.realizedResultCorrectionAware ? ru(market.realizedResultGp) + " gp"
  + (corrected ? msg("cy") : "") : "0 gp"));
 }
 if (market.settlementAdjustmentGp != 0L && market.inferredGeTaxGp <= 0L) {
  // An unexplained gap is the receipt's own answer and must stay visible.
  lines.add("Adjustment|" + ru(market.settlementAdjustmentGp) + " gp");
 }
 if (market.geDifferenceAvailable) {
  // After-tax comparable: SELL compares net received cash with the tax-adjusted
  // reference, never with a gross pre-tax number. Execution/reference only.
  if (!sell && market.basisUnitPrice > 0L) lines.add("GE reference|" + exact(market.basisUnitPrice) + " gp ea");
  lines.add("GE difference|" + ru(market.geDifferenceGp) + " gp");
 }
 return lines;
}

/** Compact fill/collected state; omitted when offered, filled and collected agree. */
static String ta(Row market) {
 long offered = market.offeredQty;
 long filled = market.filledQty;
 long collected = market.settledQty;
 if (offered <= 0L || (filled == collected && collected == offered)) return "";
 if (filled == collected) return "Filled " + exact(collected) + " / " + exact(offered);
 return "Filled " + exact(filled) + " / " + exact(offered) + " \u00b7 collected " + exact(collected);
}

/** Order-state wording that never mislabels placement time as settlement time. */
static String acp(Row market) {
 boolean sell = market.side == SELL;
 String side = sell ? "Sell order" : "Buy order";
 switch (market.lifecycle) {
  case CANCELLED_RETURNED:
  return msg("ji");
  case AMBIGUOUS:
  return "Needs review";
  case UNAVAILABLE:
  return "Unavailable";
  case CLOSED_UNOBSERVED:
  return "Unobserved";
  case EXECUTED_UNSETTLED:
  return (sell ? "Sold " : "Bought ") + exact(market.filledQty) + "/" + exact(market.offeredQty) + msg("jj");
  case PARTIALLY_EXECUTED:
  return (sell ? "Part sold " : "Part bought ") + exact(market.filledQty)
  + "/" + exact(market.offeredQty) + " \u00b7 Pending";
  default:
  return avj(market);
 }
}

static String awu(Row market) {
 switch (market.lifecycle) {
  case CANCELLED_RETURNED:
  return msg("jk");
  case AMBIGUOUS:
  return msg("ge");
  case EXECUTED_UNSETTLED:
  return msg("gf");
  default:
  return msg("j");
 }
}

static String auo(Group group) {
 if (group.market) return group.qe;
 if (!group.usedBy.isEmpty()) return "Used by " + group.usedBy;
 return group.actionLabel;
}
}

