 if (splittable) {
  list.put("Split…", () -> actions.split(transactionId, (split, preview) -> {
   ou();
   pendingTransaction = transactionId;
   pendingSplit = split;
   pendingPreview = preview;
   auy(transactionId, contributionId);
  }));
 }
 list.put(msg("fb"), actions::undoCorrection);
 return list;
}

