package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Generic fallbacks are not activities: they never become the session's activity label. */
public class ActivityDetectorTest
{
    @Test
    public void npcLootFallbackNeverBecomesTheActivity()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        };
        Am engine = new Am(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.rm(1_000L);
        ActivityDetector detector = new ActivityDetector(config, engine);

        detector.abm("Woodcutting", true);
        assertEquals("Woodcutting", engine.getMetrics(1_100L).activityHint);

        detector.abm("NPC loot", true);
        assertEquals("a fallback is not an activity", "Woodcutting", engine.getMetrics(1_200L).activityHint);
    }

    @Test
    public void aGatherClickNamesNothingUntilItsSkillsFirstXp()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        };
        Am engine = new Am(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.rm(1_000L);
        ActivityDetector detector = new ActivityDetector(config, engine);

        // Clicking a tree with no axe, or before reaching it.
        detector.gatherSkill = Dw.ka("chop down");
        assertEquals("General", engine.getMetrics(1_100L).activityHint);
        // Other XP still needs its second drop.
        detector.acj("Mining", null, false, 1_200L);
        assertEquals("General", engine.getMetrics(1_300L).activityHint);
        // The first log's XP names the run at once.
        detector.acj("Woodcutting", null, false, 1_400L);
        assertEquals("Woodcutting", engine.getMetrics(1_500L).activityHint);
    }

    /**
     * Owner report 2026-09-28: iron smelting fails about half the time with no XP, so the six-tick
     * window lapsed between successes and the next ore-to-bar change became a Review row. A
     * production skill's XP keeps the run in PRODUCTION for 30 s after the last one.
     */
    @Test
    public void aSmeltingRunSurvivesFailedSmeltsWithoutXp()
    {
        GpManagerConfig config = new GpManagerConfig() {};
        Am engine = new Am(deltas -> Collections.emptyList(),
            new TransactionClassifier(), config);
        engine.rm(1_000L);
        ActivityDetector detector = new ActivityDetector(config, engine);
        long now = 1_000_000L;

        detector.le("Smelting", now);
        engine.eb.drop(Eb.CT); // two failed smelts: the six-tick window has lapsed
        detector.acj("Smithing", null, false, now + 12_000L);
        assertEquals(Aj.PRODUCTION, engine.ac().context);
        assertTrue("Smithing XP re-arms the run", engine.ct() > 0);

        engine.eb.drop(Eb.CT);
        detector.acj("Attack", null, false, now + 17_000L);
        assertEquals("combat XP never opens production", 0, engine.ct());

        detector.acj("Smithing", null, false, now + 12_000L + 31_000L);
        assertEquals("past the run window XP no longer re-arms", 0, engine.ct());
    }
}

package com.gpmanager;
import java.util.*;
/**
* Agility courses by map region, so Agility XP earns a named activity ("Wilderness Agility
* Course") instead of the bare skill. Presentation / activity naming only — accounting never
* reads this. Region ids follow the wiki course maps (and RuneLite's agility plugin).
*/
class Ago {
static final Map<Integer, String> BY_REGION = Ak.byId("d14");
/** Course name for a region, or null when the region is not a known course. */
static String qp(int /* regionId */a) {
 return BY_REGION.get(a);
}

/** The Wilderness course's reward dispenser and the Brimhaven ticket dispenser. */
static boolean xd(String /* target */a) {
 if (a == null) return false;
 String /* lower */b = Ag.lower(a);
 return Ag.has(b, "agility dispenser", "ticket dispenser");
}
}

package com.gpmanager;
import static com.gpmanager.Ak.msg;
import java.util.*;
/**
* The one activity label HUD+ and Live both show. It never names an NPC (owner 1.1: other plugins
* do): a named Grind, else a raid, minigame or skilling activity, else "Combat" for fighting and
* NPC loot. Generic placeholders never surface. Presentation only: it never books or values.
*/
class Alo {
/** Raids and minigames whose session name outranks a fresh target. */
static final List<String> CURATED = Arrays.asList("theatre of blood", "chambers of xeric",
"tombs of amascut", msg("fe"), "barbarian assault", "tempoross", "wintertodt", "inferno",
"fight caves", "colosseum", "nightmare", "gauntlet");
static final List<String> CURATED_SHORT = Arrays.asList("tob", "cox", "toa", "gotr");
/** XP in these is fighting, not an activity of its own. */
static final List<String> COMBAT = Arrays.asList("Attack", "Strength", "Defence", "Ranged", "Hitpoints");

/** The status-line label: the named run, else a named activity, else Combat, else empty. */
static String resolve(boolean /* fighting */a, String /* activity */b, String /* ownerLabel */c, boolean /* hasSession */d, boolean /* freePlay */e) {
 if (d && !e) return Fmt.activity(c);
 String /* hint */f = clean(b);
 if (named(f)) return Fmt.activity(f);
 // What is left came from fighting: an NPC's loot names it, or combat XP.
 return a || !f.isEmpty() ? "Combat" : "";
}

/** A raid, minigame, skill, agility course or one of the named pursuits; never an NPC. */
static boolean named(String /* hint */a) {
 if (curated(a) || AgilityCourses.BY_REGION.containsValue(a)
 || Arrays.asList("PKing", "Trading", "Death reclaim").contains(a)) return true;
 for (net.runelite.api.Skill /* skill */b : net.runelite.api.Skill.values()) {
  if (b.getName().equalsIgnoreCase(a)) return !COMBAT.contains(b.getName());
 }
 return false;
}

/** True when the session activity is a raid or minigame that keeps its name over a target. */
static boolean curated(String /* activity */a) {
 String /* lower */b = Ag.lower(a);
 if (b.isEmpty()) return false;
 if (CURATED_SHORT.contains(b)) return true;
 for (String /* name */c : CURATED) {
  if (b.contains(c)) return true;
 }
 return false;
}

/** Trim, and drop generic placeholders that are not activities. */
static String clean(String /* value */a) {
 String /* trimmed */b = a == null ? "" : a.trim();
 return b.isEmpty() || "General".equalsIgnoreCase(b) || "NPC loot".equalsIgnoreCase(b) ? "" : b;
}
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;

/** Retained bank contents are not proof that the bank interface is still open. */
public class BankVisibilityRegressionTest
{
    @Test public void cachedBankAfterCloseDoesNotSuppressHarvestOrSupplies() throws Exception
    {
        for (int itemId : new int[] {1942, 1947, 1511, 1519, 385})
        {
            boolean consuming = itemId == 385;
            GpManagerConfig config = new GpManagerConfig() {
                public int stabilizationTicks() { return 0; }
            };
            Am engine = new Am(deltas -> {
                java.util.List<Ab> flows = new java.util.ArrayList<>();
                deltas.forEach((id, qty) -> flows.add(new Ab(id, "Item " + id, qty, 50, qty * 50)));
                return flows;
            }, new TransactionClassifier(), config);
            engine.rm(1000);
            Cc held = new Cc(Collections.singletonMap(itemId, 1L));
            engine.setBaseline(consuming ? held : Cc.empty());
            // The same bank visibility decision used by the production tick adapter.
            if (bankOpen(false)) engine.ze(6);
            else engine.yu();
            engine.yz();
            Cc next = consuming ? Cc.empty() : held;
            engine.adj(next, 1600);
            assertEquals(consuming ? Ai.CONSUMPTION : Ai.GAIN,
                engine.adj(next, 2200).getType());
            assertEquals(consuming ? -50 : 50, engine.getMetrics(2200).net);
        }
    }

    @Test public void visibleBankStillSuppressesTransfers() throws Exception
    {
        assertTrue(bankOpen(true));
    }

    @Test public void toolLeprechaunStoreIsStorageOnlyWhileItsWindowShows()
    {
        Widget shown = proxy(Widget.class, name -> "isHidden".equals(name) ? false : null);
        Client open = proxy(Client.class, name -> "getWidget".equals(name) ? shown : null);
        Client closed = proxy(Client.class, name -> null);
        assertTrue(Ee.yf(open));
        assertFalse(Ee.yf(closed));
    }

    /**
     * Owner 2026-10-08: storing in or taking from a store with its own window (Elnock, the seed
     * vault, a cargo hold, Death's coffer, item sets...) is no loot. Every d29 row names a real
     * RuneLite component, and only that store's window gives its note.
     */
    @Test public void storeWindowsAreStorageWhileEitherPanelShows() throws Exception
    {
        Widget shown = proxy(Widget.class, name -> "isHidden".equals(name) ? false : null);
        assertTrue(Ee.STORES.size() >= 16);
        for (String[] row : Ee.STORES)
        {
            String[] name = row[1].split("\\.");
            int component = Class.forName("net.runelite.api.gameval.InterfaceID$" + name[0])
                .getField(name[1]).getInt(null);
            assertEquals(row[1], component, Integer.parseInt(row[0]));
            Client open = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
                (obj, method, args) -> "getWidget".equals(method.getName()) && args.length == 1
                    && Integer.valueOf(component).equals(args[0]) ? shown : null);
            assertEquals(row[1], row[2], Ee.store(open));
            assertFalse("not the tool store", Ee.yf(open));
            assertFalse("not the Grand Exchange", Ee.wq(open));
        }
        assertNull(Ee.store(proxy(Client.class, name -> null)));
    }

    /** A banker's collection box collects Grand Exchange offers: a Collect there is GE evidence. */
    @Test public void collectionBoxCountsAsTheGrandExchange()
    {
        Widget shown = proxy(Widget.class, name -> "isHidden".equals(name) ? false : null);
        int box = net.runelite.api.gameval.InterfaceID.GeCollect.UNIVERSE;
        Client open = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (obj, method, args) -> "getWidget".equals(method.getName()) && args.length == 1
                && Integer.valueOf(box).equals(args[0]) ? shown : null);
        assertTrue(Ee.wq(open));
        assertFalse(Ee.wq(proxy(Client.class, name -> null)));
    }

    private boolean bankOpen(boolean visible) throws Exception
    {
        ItemContainer cachedBank = proxy(ItemContainer.class, (name) -> null);
        Widget widget = proxy(Widget.class, name -> "isHidden".equals(name) ? !visible : null);
        Client client = proxy(Client.class, name -> {
            if ("getItemContainer".equals(name)) return cachedBank;
            if ("getWidget".equals(name)) return widget;
            return null;
        });
        return Ee.vp(client);
    }

    private static <T> T proxy(Class<T> type, java.util.function.Function<String, Object> values)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, (obj, method, args) -> {
            Object value = values.apply(method.getName());
            if (value != null || !method.getReturnType().isPrimitive()) return value;
            if (method.getReturnType() == boolean.class) return false;
            if (method.getReturnType() == long.class) return 0L;
            return 0;
        }));
    }
}

