package com.gpmanager;
import static com.gpmanager.Ak.msg;
import java.util.*;
import lombok.*;
import static java.util.Locale.*;
/**
* Item Retrieval Services and their published flat fees. Source: OSRS Wiki
* "Item Retrieval Service" (checked 2026-09-13). The fee here is an <em>expectation used
* for labelling</em>; the booked cost is always the coins actually observed leaving the
* inventory in the reclaim window. Fees paid from the bank or Death's Coffer are not
* observable and are never invented.
*/
class Bro {
/** Marker for services whose fee depends on the run (ToA scales with raid level). */
static final long VARIABLE_FEE = -1L;
/** Marker for tiered / percentage fees (gravestone, Death's Office) — see DeathReclaimFees. */
static final long TIERED_FEE = -2L;
@AllArgsConstructor
static class Service {
 String key;
 String activity;
 String interactable;
 long expectedFee;
 String note;
 /**
 * Target name shared with unrelated scenery (a bare "Chest", a gravestone): only
 * evidence when a local PvM death is still awaiting reclaim.
 */
 boolean ambiguousTarget;
 /** Ledger explanation for an observed coin payment at this service. */
 String why(long /* observedCoins */b) {
  var /* why */c = new StringBuilder(msg("a4")).append(activity).append(" (").append(interactable).append(")");
  if (expectedFee > 0L) {
   c.append(", published ").append(String.format(ROOT, "%,d", expectedFee));
   if (b > 0L && b != expectedFee) {
    c.append(", observed ").append(String.format(ROOT, "%,d", b));
   }
  } else if (expectedFee == VARIABLE_FEE) {
   c.append(", fee varies");
  }
  if (!note.isEmpty()) c.append(". ").append(note);
  return c.toString();
 }
}

static final Map<String, Service> BY_INTERACTABLE = new LinkedHashMap<>();
static {
 for (String[] r : Ak.rows("d2")) {
  BY_INTERACTABLE.put(r[2].toLowerCase(ROOT),
  new Service(r[0], r[1], r[2], Long.parseLong(r[3]), r[4], Boolean.parseBoolean(r[5])));
 }
}

/**
* Service for a menu target (NPC or object name) when the option is a retrieval verb
* (see {@link #isRetrievalOption}). Ambiguous targets ("Chest", "Gravestone", "Death")
* are returned too; the engine only acts on them while a local PvM death awaits reclaim.
*/
static Service axr(String /* option */a, String /* target */b) {
 if (b == null || a == null || !Ag.lower(a).matches(msg("e"))) {
  return null;
 }
 String /* lower */c = Ag.lower(b);
 if (c.isEmpty()) return null;
 Service /* exact */d = BY_INTERACTABLE.get(c);
 if (d != null) return d;
 for (Map.Entry<String, Service> /* entry */f : BY_INTERACTABLE.entrySet()) {
  if (!f.getValue().ambiguousTarget && c.contains(f.getKey())) return f.getValue();
 }
 if (c.startsWith("gravestone") || c.startsWith("grave")) return BY_INTERACTABLE.get("gravestone");
 return null;
}

/** Menu verbs that open or complete a reclaim. */}

package com.gpmanager;

import java.io.InputStream;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Properties;
import javax.annotation.Nullable;

/**
 * Immutable build-time identity for development builds (dev launcher and panel preview only; the
 * plugin itself has no build-identity code). Build metadata only: never financial,
 * never owner-scoped and never persisted. The Gradle build writes the bundled resource; runtime
 * reads ordinary immutable data (no process execution, no networking, no reflection).
 *
 * <p>Missing or corrupt metadata degrades to a bare {@code DEV BUILD} marker instead of failing
 * plugin startup.</p>
 */
public final class BuildInfo
{
    /** Build-generated resource, written by Gradle into the plugin resources. */
    static final String RESOURCE = "/gp-manager-build.properties";

    private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm'Z'")
        .withZone(ZoneOffset.UTC);
    private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss 'UTC'")
        .withZone(ZoneOffset.UTC);
    private static final int MAX_FIELD = 48;

    private final String version;
    private final String developmentVersion;
    private final String schemaVersion;
    private final String builtAtUtc;
    private final String revision;
    private final String runeliteDependency;
    private final boolean development;

    private BuildInfo(String version, String developmentVersion, String schemaVersion,
        String builtAtUtc, String revision, String runeliteDependency, boolean development)
    {
        this.version = safe(version);
        this.developmentVersion = safe(developmentVersion);
        this.schemaVersion = safe(schemaVersion);
        this.builtAtUtc = safe(builtAtUtc);
        this.revision = safe(revision);
        this.runeliteDependency = safe(runeliteDependency);
        this.development = development;
    }

    /** Reads the bundled build metadata; any failure yields the harmless fallback. */
    public static BuildInfo load()
    {
        return load(BuildInfo.class.getResourceAsStream(RESOURCE));
    }

    /** Explicit-stream load for tests and previews; the stream is closed here. */
    public static BuildInfo load(@Nullable InputStream stream)
    {
        if (stream == null)
        {
            return fallback();
        }
        Properties properties = new Properties();
        try (InputStream in = stream)
        {
            properties.load(in);
        }
        catch (Exception ex)
        {
            return fallback();
        }
        String version = properties.getProperty("version");
        String developmentVersion = properties.getProperty("developmentVersion");
        if (safe(version).isEmpty() && safe(developmentVersion).isEmpty())
        {
            return fallback();
        }
        return new BuildInfo(
            version,
            developmentVersion,
            properties.getProperty("schema"),
            properties.getProperty("builtAt"),
            properties.getProperty("revision"),
            properties.getProperty("runeliteDependency"),
            "true".equalsIgnoreCase(safe(properties.getProperty("development"))));
    }

    /** Injection seam for previews/tests: an explicit, fixed identity. */
    public static BuildInfo of(@Nullable String version, @Nullable String developmentVersion,
        @Nullable String schemaVersion, @Nullable String builtAtUtc, @Nullable String revision,
        @Nullable String runeliteDependency, boolean development)
    {
        return new BuildInfo(version, developmentVersion, schemaVersion, builtAtUtc, revision,
            runeliteDependency, development);
    }

    /** Safe fallback when optional metadata is missing or unreadable. */
    public static BuildInfo fallback()
    {
        return new BuildInfo("", "", "", "", "", "", true);
    }

    public boolean development()
    {
        return development;
    }

    public String version()
    {
        return version;
    }

    public String developmentVersion()
    {
        return developmentVersion;
    }

    public String schemaVersion()
    {
        return schemaVersion;
    }

    public String revision()
    {
        return revision;
    }

    /**
     * The tiny footer marker: {@code DEV · 1.2.0 · 01:24Z}. Release builds return an empty
     * string, so the footer collapses instead of showing a stale development marker.
     */
    public String badgeText()
    {
        if (!development)
        {
            return "";
        }
        if (version.isEmpty())
        {
            return "DEV BUILD";
        }
        String clock = clockUtc();
        return clock.isEmpty() ? "DEV \u00b7 " + version : "DEV \u00b7 " + version + " \u00b7 " + clock;
    }

    /** Full identity for the footer tooltip and accessibility description. */
    public String tooltipText()
    {
        StringBuilder text = new StringBuilder(development
            ? "GP Manager Development Build" : "GP Manager Release Build");
        String shownVersion = developmentVersion.isEmpty() ? version : developmentVersion;
        if (!shownVersion.isEmpty())
        {
            text.append("\nVersion: ").append(shownVersion);
        }
        if (!schemaVersion.isEmpty())
        {
            text.append("\nSchema: ").append(schemaVersion);
        }
        String stamp = stampUtc();
        if (!stamp.isEmpty())
        {
            text.append("\nBuilt: ").append(stamp);
        }
        if (!runeliteDependency.isEmpty())
        {
            text.append("\nRuneLite: ").append(runeliteDependency);
        }
        if (!revision.isEmpty())
        {
            text.append("\nRevision: ").append(revision);
        }
        return text.toString();
    }

    /** Compact UTC clock of the build, or empty when no usable timestamp is bundled. */
    public String clockUtc()
    {
        Instant instant = parsedBuiltAt();
        return instant == null ? "" : CLOCK.format(instant);
    }

    /** Full UTC timestamp of the build, or the raw bundled text when unparseable. */
    public String stampUtc()
    {
        Instant instant = parsedBuiltAt();
        return instant == null ? builtAtUtc : STAMP.format(instant);
    }

    @Nullable
    private Instant parsedBuiltAt()
    {
        if (builtAtUtc.isEmpty())
        {
            return null;
        }
        try
        {
            return Instant.parse(builtAtUtc);
        }
        catch (RuntimeException ex)
        {
            return null;
        }
    }

    private static String safe(@Nullable String value)
    {
        if (value == null)
        {
            return "";
        }
        StringBuilder clean = new StringBuilder(Math.min(value.length(), MAX_FIELD));
        for (int i = 0; i < value.length() && clean.length() < MAX_FIELD; i++)
        {
            char c = value.charAt(i);
            if (!Character.isISOControl(c))
            {
                clean.append(c);
            }
        }
        return clean.toString().trim();
    }
}

package com.gpmanager;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Build identity is ordinary immutable metadata: parsed, displayed and fail-safe. */
public class BuildInfoTest
{
    @Test
    public void developmentMetadataParsesIntoTheTinyFooterMarker()
    {
        BuildInfo info = BuildInfo.load(stream("version=1.2.0\n"
            + "developmentVersion=1.2.0-dev\n"
            + "development=true\n"
            + "schema=105\n"
            + "builtAt=2026-09-23T01:24:37Z\n"
            + "revision=2929696\n"
            + "runeliteDependency=1.12.39\n"));

        assertTrue(info.development());
        assertEquals("1.2.0", info.version());
        assertEquals("1.2.0-dev", info.developmentVersion());
        assertEquals("105", info.schemaVersion());
        assertEquals("2929696", info.revision());
        assertEquals("DEV \u00b7 1.2.0 \u00b7 01:24Z", info.badgeText());
        assertTrue(info.tooltipText().contains("GP Manager Development Build"));
        assertTrue(info.tooltipText().contains("Version: 1.2.0-dev"));
        assertTrue(info.tooltipText().contains("Schema: 105"));
        assertTrue(info.tooltipText().contains("Built: 2026-09-23 01:24:37 UTC"));
        assertTrue(info.tooltipText().contains("RuneLite: 1.12.39"));
        assertTrue(info.tooltipText().contains("Revision: 2929696"));
    }

    @Test
    public void releaseMetadataOmitsTheDevelopmentMarker()
    {
        BuildInfo info = BuildInfo.load(stream("version=1.0.0\n"
            + "developmentVersion=1.0.0\n"
            + "development=false\n"
            + "schema=105\n"
            + "builtAt=2026-09-23T01:24:37Z\n"));

        assertFalse(info.development());
        assertEquals("", info.badgeText());
    }

    @Test
    public void missingMetadataFallsBackWithoutFailing()
    {
        BuildInfo info = BuildInfo.load((java.io.InputStream) null);

        assertTrue("a missing resource still identifies the running build", info.development());
        assertEquals("DEV BUILD", info.badgeText());
        assertTrue(info.tooltipText().contains("GP Manager Development Build"));
    }

    @Test
    public void corruptMetadataFailsSafelyAndNeverLeaksControlCharacters()
    {
        BuildInfo info = BuildInfo.load(stream("not=properties\n\u0000\u0001version=\u0007garbage\u0000\n"));

        // No usable version survives, so the marker degrades to the bare development form.
        assertEquals("DEV BUILD", info.badgeText());
        for (int i = 0; i < info.badgeText().length(); i++)
        {
            assertFalse(Character.isISOControl(info.badgeText().charAt(i)));
        }
    }

    @Test
    public void unparseableTimestampKeepsTheVersionAndDropsOnlyTheClock()
    {
        BuildInfo info = BuildInfo.load(stream("version=1.2.0\n"
            + "developmentVersion=1.2.0-dev\n"
            + "development=true\n"
            + "builtAt=not-a-timestamp\n"));

        assertEquals("DEV \u00b7 1.2.0", info.badgeText());
        assertTrue(info.tooltipText().contains("Built: not-a-timestamp"));
    }

    @Test
    public void injectedFixedIdentityDoesNotDependOnTheWallClock()
    {
        BuildInfo info = BuildInfo.of("1.2.0", "1.2.0-dev", "105",
            "2026-09-23T11:42:05Z", "abcdef1", "1.12.39", true);

        assertEquals("DEV \u00b7 1.2.0 \u00b7 11:42Z", info.badgeText());
    }

    private static ByteArrayInputStream stream(String text)
    {
        return new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));
    }
}

