        assertFalse(ChargeIntake.lg(Ar.V.CRYSTAL_BOW, AnimationID.HUMAN_SWORD_SLASH));
        assertEquals(Long.valueOf(1L),
            ChargeIntake.recipeOf(Ar.V.SAELDOR).get(ItemID.PRIF_CRYSTAL_SHARD));
        assertEquals(100, Ar.akr(Ar.V.SAELDOR, ItemID.PRIF_CRYSTAL_SHARD));
        assertEquals(Ar.V.SAELDOR, Ar.aja(ItemID.BLADE_OF_SAELDOR));
        assertEquals(Ar.V.SAELDOR, Ar.aja(ItemID.BLADE_OF_SAELDOR_INACTIVE));
        assertEquals("the restart icon fallback resolves the blade",
            Ar.V.SAELDOR, Ar.ajt("Blade of Saeldor"));
    }

    @Test
    public void corruptedCrystalWeaponsStayUnmatchedAndTheEchoBowSharesItsFamily()
    {
        assertEquals(2289, ChargeProbes.nx(Ar.V.VENATOR_ECHO));
        assertEquals(Au.FIRE, ChargeIntake.rw(Ar.V.VENATOR_ECHO));
        assertEquals(Long.valueOf(1L),
            ChargeIntake.recipeOf(Ar.V.VENATOR_ECHO).get(ItemID.ANCIENT_ESSENCE));
        assertNull("corrupted (permanently charged) crystal weapons cost nothing",
            Ar.aja(ItemID.BOW_OF_FAERDHINEN_INFINITE));
        assertNull(Ar.aja(ItemID.BOW_OF_FAERDHINEN_INFINITE_ITHELL));
        assertNull(Ar.aja(ItemID.BLADE_OF_SAELDOR_INFINITE));
    }

    @Test
    public void fractionalComponentsAccrueWholeUnits()
    {
        assertArrayEquals(new long[]{Ar.SCALES, 2L, 3L},
            ChargeIntake.tw(Ar.V.V1b));
        assertArrayEquals(new long[]{ItemID.VIAL_BLOOD, 1L, 100L},
            ChargeIntake.tw(Ar.V.SCYTHE));
        assertNull(ChargeIntake.tw(Ar.V.SHADOW));

        assertArrayEquals(new long[]{0L, 2L}, ChargeIntake.accrue(0L, 2L, 3L));
        assertArrayEquals(new long[]{1L, 1L}, ChargeIntake.accrue(2L, 2L, 3L));
        assertArrayEquals(new long[]{1L, 0L}, ChargeIntake.accrue(1L, 2L, 3L));
        assertArrayEquals(new long[]{0L, 99L}, ChargeIntake.accrue(98L, 1L, 100L));
        assertArrayEquals(new long[]{1L, 0L}, ChargeIntake.accrue(99L, 1L, 100L));
    }

    @Test
    public void wornEstimateIdentityMatchesTheWornCheckIdentity()
    {
        int equipmentWidget = InterfaceID.Wornitems.UNIVERSE;
        assertEquals((equipmentWidget >>> 16) + ":3:" + ItemID.TOTS_CHARGED + ":TRIDENT_SEAS",
            ChargeIntake.akz(Ar.V.TRIDENT_SEAS,
                ItemID.TOTS_CHARGED));
    }

    @Test
    public void sameVariantChargeStateSwapsAreNeutralButRealMovementsStay()
    {
        Ab full = flow(ItemID.TOTS, "Trident of the Seas (full)", -1L, 845_298L);
        Ab partial = flow(ItemID.TOTS_CHARGED, "Trident of the Seas", 1L, 39_867L);
        Ab rune = flow(ItemID.DEATHRUNE, "Death rune", -1L, 100L);

        assertTrue(Dv.akq(Arrays.asList(full, partial)).isEmpty());
        assertEquals(1, Dv.akq(Arrays.asList(full, partial, rune)).size());
        assertEquals(1, Dv.akq(Collections.singletonList(full)).size());

        Ab swamp = flow(ItemID.TOXIC_TOTS_CHARGED, "Trident of the Swamp", -1L, 3_000L);
        assertEquals(2, Dv.akq(Arrays.asList(swamp, partial)).size());
    }

    private static Ab flow(int itemId, String name, long quantity, long unitPrice)
    {
        return new Ab(itemId, name, quantity, (int) unitPrice, quantity * unitPrice,
            Av.GRAND_EXCHANGE);
    }
}

package com.gpmanager;

import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

/** Owner 2026-09-29: the eye books its tears; blood fury books per melee hit, not per Check. */
public class ChargeHitEstimateTest
{
    @Test
    public void eyeChargeLineIsAParsedTearRead()
    {
        Ar eye = Ar.acs("The Eye of Ayak has been charged with demon tears. It currently has 1,996 charges.");
        assertNotNull("the owner's live line must parse", eye);
        assertEquals(Ar.V.EYE_OF_AYAK, eye.variant);
        assertTrue(eye.bookable);
        assertEquals(Long.valueOf(1_996L), eye.componentCounts.get(ItemID.DEMON_TEAR));
    }

    @Test
    public void eyeLoadsValidateForBothChargingModes()
    {
        assertTrue(Ar.xq(Ar.V.EYE_OF_AYAK, ItemID.DEMON_TEAR, "Demon tear"));
        assertTrue(Ar.xq(Ar.V.EYE_OF_AYAK, ItemID.DEATHRUNE, "Death rune"));
        assertTrue(Ar.xq(Ar.V.EYE_OF_AYAK, ItemID.CHAOSRUNE, "Chaos rune"));
        assertFalse("an unrelated rune never validates as an eye load",
            Ar.xq(Ar.V.EYE_OF_AYAK, ItemID.BLOODRUNE, "Blood rune"));
    }

    @Test
    public void eyeRecipeFollowsItsOwnChargingMode()
    {
        assertEquals(Long.valueOf(1L), ChargeIntake.eyeRecipe(false).get(ItemID.DEMON_TEAR));
        assertNull(ChargeIntake.eyeRecipe(false).get(ItemID.DEATHRUNE));
        assertEquals(Long.valueOf(2L), ChargeIntake.eyeRecipe(true).get(ItemID.DEATHRUNE));
        assertEquals(Long.valueOf(1L), ChargeIntake.eyeRecipe(true).get(ItemID.CHAOSRUNE));
        assertNull("a rune-charged eye never estimates tears",
            ChargeIntake.eyeRecipe(true).get(ItemID.DEMON_TEAR));
    }

    @Test
    public void eyeRuneModeParsesAsRunesNotTears()
    {
        Ar runes = Ar.acs("The Eye of Ayak has been charged with runes. It currently has 98 charges.");
        assertNotNull(runes);
        assertEquals(Ar.V.EYE_OF_AYAK, runes.variant);
        assertEquals(Long.valueOf(196L), runes.componentCounts.get(ItemID.DEATHRUNE));
        assertEquals(Long.valueOf(98L), runes.componentCounts.get(ItemID.CHAOSRUNE));
        assertNull("a rune-charged eye never books demon tears",
            runes.componentCounts.get(ItemID.DEMON_TEAR));
    }

    @Test
    public void eyeIsAChargeMeasuredFamilyAtOneTearPerCharge()
    {
        assertTrue(Ar.V.EYE_OF_AYAK.implemented);
        assertEquals(1, Ar.akr(Ar.V.EYE_OF_AYAK, ItemID.DEMON_TEAR));
    }

    @Test
    public void eyeCastsBookOneDemonTearLikeASpell()
    {
        assertEquals(Au.CAST, ChargeIntake.rw(Ar.V.EYE_OF_AYAK));
        assertEquals(Long.valueOf(1L), ChargeIntake.recipeOf(Ar.V.EYE_OF_AYAK).get(ItemID.DEMON_TEAR));
        assertEquals(1, Ar.akr(Ar.V.EYE_OF_AYAK, ItemID.DEMON_TEAR));
    }

    @Test
    public void magicXpPinsTheEyesOwnCastTrigger()
    {
        ChargeIntake intake = new ChargeIntake(null, null, null, null, null);
        intake.eyeCandidateAnimation = 9276;
        intake.eyeCandidateTick = 10;
        intake.aks(Skill.MAGIC, 11, 11_000L);
        assertTrue(intake.eyeAnimations.contains(9276));
        assertTrue("the proven candidate never leaks into a later cast", intake.eyeCandidateTick < 0);
        intake.eyeCandidateGraphic = 7000;
        intake.eyeCandidateTick = 20;
        intake.aks(Skill.MAGIC, 21, 21_000L);
        assertTrue("the cast graphic is learned too, so a once-only animation cannot starve it",
            intake.eyeGraphics.contains(7000));
    }

    @Test
    public void combatXpStyleDecidesMeleeForEveryWeapon()
    {
        ChargeIntake intake = new ChargeIntake(null, null, null, null, null);
        assertFalse(intake.furyMelee(10));
        intake.aks(Skill.ATTACK, 10, 10_000L);
        assertTrue("melee XP confirms the stance", intake.furyMelee(12));
        intake.aks(Skill.RANGED, 20, 20_000L);
        assertFalse("ranged XP denies melee", intake.furyMelee(21));
        intake.aks(Skill.DEFENCE, 30, 30_000L);
        assertTrue("defensive melee counts too", intake.furyMelee(32));
        intake.aks(Skill.MAGIC, 40, 40_000L);
        assertFalse("magic XP denies melee", intake.furyMelee(41));
        intake.aks(Skill.ATTACK, 100, 100_000L);
        assertFalse("a stale stance expires", intake.furyMelee(200));
    }

    @Test
    public void furyEstimatesOneTenThousandthOfAShardPerCountedHit()
    {
        // The hit estimate must price in hit units, so the Check delta reconciles on the same scale.
        assertEquals(Au.SUPPLIES, ChargeIntake.rw(Ar.V.BLOOD_FURY));
        assertEquals(Long.valueOf(1L), ChargeIntake.recipeOf(Ar.V.BLOOD_FURY).get(ItemID.BLOOD_SHARD));
        assertEquals(10_000, Ar.akr(Ar.V.BLOOD_FURY, ItemID.BLOOD_SHARD));
    }

    @Test
    public void seasTridentEstimatesBookTenCoinsPerCast()
    {
        assertEquals(Long.valueOf(10L), ChargeIntake.recipeOf(Ar.V.TRIDENT_SEAS).get(ItemID.COINS));
        assertEquals(Long.valueOf(10L),
            ChargeIntake.recipeOf(Ar.V.TRIDENT_SEAS_ENHANCED).get(ItemID.COINS));
    }

    @Test
    public void fractionalPricingCarriesTheWholeItemValueExactly()
    {
        ChargeIntake intake = new ChargeIntake(null, null, null, null, null);
        // 100 units of a 101-gp item: the first 50 book 50, the next 50 book 51 — 101 in total.
        assertEquals(50L, intake.carriedValue(Ar.V.BLOOD_FURY, 1, 50L, 101, 100));
        assertEquals(51L, intake.carriedValue(Ar.V.BLOOD_FURY, 1, 50L, 101, 100));
        ChargeIntake other = new ChargeIntake(null, null, null, null, null);
        assertEquals("a fresh window books the whole item at once", 101L,
            other.carriedValue(Ar.V.BLOOD_FURY, 1, 100L, 101, 100));
    }

    @Test
    public void eyeModeIsTrackedPerIdentity()
    {
        ChargeIntake intake = new ChargeIntake(null, null, null, null, null);
        intake.eyeRunes.put("a", true);
        assertTrue("the rune-charged staff reads runes", intake.eyeRune("a"));
        assertFalse("another staff keeps the tear default", intake.eyeRune("b"));
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Owner 1.2: charging any charged item moves its components into charges; it never books a loss. */
public class ChargeLoadAnyItemTest
{
    private static final long T0 = 1_000_000L;

    @Test
    public void everyItemsOwnChargeMaterialIsALoad()
    {
        assertTrue(Ar.xq(Ar.V.CRYSTAL_BOW, ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard"));
        assertTrue(Ar.xq(Ar.V.SANGUINESTI, ItemID.BLOODRUNE, "Blood rune"));
        assertTrue(Ar.xq(Ar.V.SHADOW, ItemID.SOULRUNE, "Soul rune"));
        assertTrue(Ar.xq(Ar.V.ATES, ItemID.FROZEN_TEAR, "Frozen tear"));
        assertTrue(Ar.xq(Ar.V.VENATOR, ItemID.ANCIENT_ESSENCE, "Ancient essence"));
        assertTrue(Ar.xq(Ar.V.CRAW, ItemID.WILD_CAVE_SHARD, "Revenant ether"));
        assertTrue("the scythe's vials too", Ar.xq(Ar.V.SCYTHE, ItemID.VIAL_BLOOD, "Vial of blood"));
        assertFalse("another item is not its charge", Ar.xq(Ar.V.SANGUINESTI, ItemID.FIRERUNE, "Fire rune"));
    }

    @Test
    public void chargingACrystalBowBooksNothing()
    {
        Am engine = settle(true);
        assertEquals(0L, engine.getMetrics(T0 + 10_000L).net);
        assertTrue(engine.getActiveSession().getTransactions().stream().noneMatch(Ac::isCounted));
    }

    @Test
    public void withoutTheLoadTheSameShardsWouldBeALoss()
    {
        assertTrue(settle(false).getMetrics(T0 + 10_000L).net < 0L);
    }

    @Test
    public void theScytheOnTheVyreWellLoadsItsRunesAndVialsThroughThePrompt()
    {
        Am engine = HudBuilderTest.engine();
        engine.rm(T0);
        engine.setBaseline(new Cc(new HashMap<>(Map.of(ItemID.BLOODRUNE, 1_000L, ItemID.VIAL_BLOOD, 5L))));
        Widget scythe = widget(ItemID.SCYTHE_OF_VITUR, 149 << 16, 3);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, args) -> "getSelectedWidget".equals(method.getName()) ? scythe
                : "getTickCount".equals(method.getName()) ? 10 : null);
        ChargeIntake intake = new ChargeIntake(client, null, HudBuilderTest.config(true, 4), engine, null);
        intake.lc(click(MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, "Use", null), "use");
        intake.lc(click(MenuAction.WIDGET_CONTINUE, "Continue", null), "continue");
        engine.yz();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.adj(new Cc(new HashMap<>(Map.of(ItemID.BLOODRUNE, 800L, ItemID.VIAL_BLOOD, 4L))), T0 + tick * 600L);
        }
        assertEquals("charging the scythe is not a cost", 0L, engine.getMetrics(T0 + 10_000L).net);
    }

    private static Am settle(boolean loaded)
    {
        Am engine = HudBuilderTest.engine();
        engine.rm(T0);
        engine.setBaseline(new Cc(new HashMap<>(Map.of(ItemID.PRIF_CRYSTAL_SHARD, 500L))));
        if (loaded)
        {
            engine.yx(Ar.V.CRYSTAL_BOW, ItemID.PRIF_CRYSTAL_SHARD, "Crystal shard", "149:0:23983:CRYSTAL_BOW",
                ChargeIntake.LOAD_TICKS);
        }
        engine.yz();
        for (int tick = 1; tick <= 5; tick++)
        {
            engine.adj(new Cc(new HashMap<>(Map.of(ItemID.PRIF_CRYSTAL_SHARD, 400L))), T0 + tick * 600L);
        }
        return engine;
    }

    static Widget widget(int itemId, int id, int index)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[]{Widget.class},
            (proxy, method, args) -> "getItemId".equals(method.getName()) ? itemId
                : "getId".equals(method.getName()) ? id : "getIndex".equals(method.getName()) ? index
                : method.getReturnType() == int.class ? 0 : method.getReturnType() == boolean.class ? false : null);
    }

    static MenuOptionClicked click(MenuAction type, String option, Widget widget)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[]{MenuEntry.class}, (proxy, method, args) ->
            {
                if ("getOption".equals(method.getName())) return option;
                if ("getTarget".equals(method.getName())) return "";
                if ("getType".equals(method.getName())) return type;
                if ("getWidget".equals(method.getName())) return widget;
                if (method.getReturnType() == boolean.class) return false;
                if (method.getReturnType() == int.class) return 0;
                if (method.getReturnType() == long.class) return 0L;
                return null;
            });
        return new MenuOptionClicked(entry);
    }
}

