    // ── extrema ───────────────────────────────────────────────────────────────

    @Test
    public void mutableWinnerOverFinalizedExtremumAndCorrectionRevealsTheNext()
    {
        Am engine = engine(Db.DAYS_30);
        Ad session = pkSession("PK", NOW - 100L * DAY);
