        assertTrue(session.qi(second.getId(), Ah.IGNORE, NOW, "wrong"));
        assertEquals("the remaining equal mutable maximum keeps the extremum",
            10_000_000L, session.ava().bestKill);
        assertTrue(session.qi(third.getId(), Ah.IGNORE, NOW, "wrong"));
        assertEquals("the finalized equal maximum still holds", 10_000_000L, session.ava().bestKill);
    }

    @Test
    public void negativeKillNetAndPositiveDeathNetFollowTheMetricFloors()
    {
        Am engine = engine(Db.DAYS_365);
        Ad session = pkSession("PK", NOW - DAY);
        engine.history.add(session);
        Bx kill = kill(engine, session, NOW - DAY);
        Ac loss = receipt(session, NOW - DAY + 1_000L, -50L);
        session.ll(loss.getId(), kill.getId(), false);
        Bx death = death(engine, session, NOW - DAY + 2_000L);
        Ac gain = receipt(session, NOW - DAY + 3_000L, 20L);
        session.ll(gain.getId(), death.getId(), false);
        Dt metrics = session.ava();
        assertEquals("best kill is floored at zero", 0L, metrics.bestKill);
        assertEquals(-50L, metrics.totalKillNet);
        assertEquals("death loss is floored at zero", 0L, metrics.largestDeathLoss);
        assertEquals(-30L, metrics.net);
    }

    // ── coverage / medians ────────────────────────────────────────────────────

    @Test
    public void zeroEncountersExposeAdditiveZeroButNoExtremaOrMedians()
    {
        Ad session = pkSession("PK", NOW - DAY);
        Dt metrics = session.ava();
        assertEquals(0, metrics.kills);
        assertEquals(0L, metrics.net);
        assertEquals(0L, metrics.bestKill);
        assertFalse(metrics.medianKillNetGp != null);
        assertFalse(metrics.medianDeathLossGp != null);
    }

    @Test
    public void mediansCoverOnlyTheRetainedDetailWindow()
    {
        Am engine = engine(Db.DAYS_30);
        Ad session = pkSession("PK", NOW - 100L * DAY);
        engine.history.add(session);
        // Three retained kills: 100, 300, 200 -> median 200.
        long[] values = {100L, 300L, 200L};
        for (int index = 0; index < values.length; index++)
        {
            Bx encounter = kill(engine, session, NOW - 10L * DAY + index);
            Ac loot = receipt(session, NOW - 10L * DAY + index + 1L, values[index]);
            session.ll(loot.getId(), encounter.getId(), false);
        }
        assertEquals(200.0d, session.ava().medianKillNetGp, 0.0d);
        assertFalse((session.ava().detailScope == Di.RETAINED_WINDOW));

        // An older kill leaves the window: its net must not influence the retained median.
        Bx old = kill(engine, session, NOW - 100L * DAY);
        Ac oldLoot = receipt(session, NOW - 100L * DAY + 1L, 1_000L);
        session.ll(oldLoot.getId(), old.getId(), false);
        engine.pkHistory.ri(engine.akf(), 30, NOW);
        assertEquals(3, session.getPkEncounters().size());
        assertEquals("the retained-window median ignores compacted detail",
            200.0d, session.ava().medianKillNetGp, 0.0d);
        assertTrue((session.ava().detailScope == Di.RETAINED_WINDOW));
    }

    @Test
    public void sessionMediansNeverUseAnotherSessionsRows()
    {
        Am engine = engine(Db.DAYS_365);
        Ad left = pkSession("left", NOW - DAY);
        Ad right = pkSession("right", NOW - DAY);
        engine.history.add(left);
        engine.history.add(right);
        Bx leftKill = kill(engine, left, NOW - DAY);
        Ac leftLoot = receipt(left, NOW - DAY + 1L, 100L);
        left.ll(leftLoot.getId(), leftKill.getId(), false);
        for (int index = 0; index < 3; index++)
        {
            Bx rightKill = kill(engine, right, NOW - DAY + 10L + index);
            Ac rightLoot = receipt(right, NOW - DAY + 11L + index, 900L + index);
            right.ll(rightLoot.getId(), rightKill.getId(), false);
        }
        assertEquals(100.0d, left.ava().medianKillNetGp, 0.0d);
        assertEquals(901.0d, right.ava().medianKillNetGp, 0.0d);
    }

    // ── rollups ───────────────────────────────────────────────────────────────

    @Test
    public void explicitDeleteIsSubtractive()
    {
        Am engine = engine(Db.DAYS_365);
        Ad session = pkSession("doomed", NOW - DAY);
        engine.history.add(session);
        kill(engine, session, NOW - DAY);
        assertEquals(1, EngineProbe.profileFacts(engine.pkHistory, engine.akf()).getKills());
        assertTrue(engine.archive.qu(session.getId()));
        assertEquals("deliberately deleted facts disappear",
            0, EngineProbe.profileFacts(engine.pkHistory, engine.akf()).getKills());
    }

    @Test
    public void practicalScaleSoakReportsABoundedPlateau()
    {
        Am engine = engine(Db.DAYS_90);
        int sessions = 250;
        int perSession = 10;
        int encounters = 0;
        for (int s = 0; s < sessions; s++)
        {
            Ad session = pkSession("s" + s, NOW - 10L * DAY);
            engine.history.add(session);
            for (int e = 0; e < perSession; e++)
            {
                long at = NOW - 5L * DAY + s * 100_000L + e * 1_000L;
                Bx encounter = kill(engine, session, at);
                Ac loot = receipt(session, at + 1L, 100L + s + e);
                session.ll(loot.getId(), encounter.getId(), false);
                encounters++;
            }
        }
        engine.pkHistory.ri(engine.akf(), 90, NOW);
        int retainedFirst = 0;
        int anchorsFirst = 0;
        for (Ad session : engine.akf())
        {
            retainedFirst += session.getPkEncounters().size();
            anchorsFirst += session.getPkAttributions().size();
        }
        assertEquals(PkHistoryArchive.MAX_DETAILED_ENCOUNTERS, retainedFirst);
        assertEquals("anchors stay proportional to live correction-eligible receipts",
            encounters, anchorsFirst);
        int sizeFirst = JsonCodec.gson().toJson(engine.qm()).length();
        long netFirst = EngineProbe.profileFacts(engine.pkHistory, engine.akf()).getNet();
        assertEquals(encounters, EngineProbe.profileFacts(engine.pkHistory, engine.akf()).getKills());

        // Finalized growth with no new correction-eligible receipts must not grow persistent state.
        Ad extra = pkSession("extra", NOW - DAY);
        engine.history.add(extra);
        for (int index = 0; index < 300; index++) kill(engine, extra, NOW - 1_000_000L + index);
        engine.pkHistory.ri(engine.akf(), 90, NOW);
        int sizeSecond = JsonCodec.gson().toJson(engine.qm()).length();
        assertEquals(encounters + 300,
            EngineProbe.profileFacts(engine.pkHistory, engine.akf()).getKills());
        int retainedSecond = 0;
        for (Ad session : engine.akf())
        {
            retainedSecond += session.getPkEncounters().size();
        }
        assertEquals(PkHistoryArchive.MAX_DETAILED_ENCOUNTERS, retainedSecond);
        assertTrue("finalized growth must not grow the serialized profile: "
            + sizeFirst + " -> " + sizeSecond, sizeSecond <= sizeFirst + 20_000);

        SavedState state = engine.qm();
        Am reloaded = engine(Db.DAYS_90);
        reloaded.restore(state, NOW);
        assertEquals(encounters + 300,
            EngineProbe.profileFacts(reloaded.pkHistory, reloaded.akf()).getKills());
        assertEquals(netFirst, EngineProbe.profileFacts(reloaded.pkHistory, reloaded.akf()).getNet());
    }

    @Test
    public void supplySplitAndCostsStayExactAcrossAnchorFinalization()
    {
        Am engine = engine(Db.DAYS_30);
        Ad session = pkSession("PK", NOW - 100L * DAY);
        engine.history.add(session);
        Bx encounter = kill(engine, session, NOW - 100L * DAY);
        Ac loot = receipt(session, NOW - 100L * DAY + 1_000L, 5_000L);
        session.ll(loot.getId(), encounter.getId(), false);
        Ac supply = supplyCost(session, NOW - 100L * DAY + 2_000L, 300L);
        session.ll(supply.getId(), encounter.getId(), true);
        Dt before = session.ava();
        assertEquals(300L, before.costs);
        assertEquals(300L, before.suppliesCosts);
        session.pj(NOW - 30L * DAY, null);
        Dt after = session.ava();
        assertEquals(before.net, after.net);
        assertEquals(before.costs, after.costs);
        assertEquals(before.suppliesCosts, after.suppliesCosts);
        assertTrue(after.costSplitAvailable);
        assertEquals(0, session.getPkAttributions().size());
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner report 2026-09-28: an Ice Barrage cast settling with a pickup showed as loose Death, Blood and
 * Water "losses" on the loot receipt, and a spell clicked while autocasting renamed the autocast.
 */
public class CastWithPickupTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final Map<Integer, String> NAMES = new HashMap<>();

    static
    {
        NAMES.put(560, "Death rune");
        NAMES.put(565, "Blood rune");
        NAMES.put(555, "Water rune");
        NAMES.put(1359, "Rune axe");
    }

    @Test
    public void aCastSettlingWithAPickupBooksAsItsOwnCast()
    {
        Am engine = engine();
        engine.ajl("Nechryael", Cx.GENERAL, T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(560, 100L);
        held.put(565, 100L);
        held.put(555, 100L);
        engine.setBaseline(new Cc(new HashMap<>(held)));
        held.put(560, 96L);
        held.put(565, 98L);
        held.put(555, 94L);
        held.put(1359, 1L);
        engine.yz();
        List<Ac> booked = new ArrayList<>();
        for (int i = 0; i < 3; i++)
        {
            Ac settled = engine.adj(new Cc(new HashMap<>(held)),
                T0 + 600L + i * 600L, booked::add);
            if (settled != null)
            {
                booked.add(settled);
            }
        }
        Ac cast = booked.stream().filter(t -> t.getActionKind() == Au.CAST).findFirst().orElse(null);
        assertNotNull("the runes book as a Cast: " + booked, cast);
        assertEquals("Ice Barrage", cast.spellName());
        assertEquals(3, cast.getFlows().size());
        assertTrue("the pickup keeps only its gain", booked.stream().anyMatch(t -> t != cast
            && t.getFlows().size() == 1 && t.getFlows().get(0).itemId == 1359 && t.isCounted()));
    }

    @Test
    public void aQueuedClickNeverRenamesTheSpellItsRunesPaid()
    {
        Ac barrage = new Ac(T0, null, Ai.CONSUMPTION, Aj.GENERIC,
            "", "Nechryael", true, Arrays.asList(new Ab(560, "Death rune", -4L, 187, -748L),
                new Ab(565, "Blood rune", -2L, 341, -682L), new Ab(555, "Water rune", -6L, 5, -30L)),
            Bd.CONFIRMED, "fixture", null);
        barrage.setActionKind(Au.CAST);
        barrage.ahu(Bb.of("Ice Burst"));
        assertEquals("Ice Barrage", barrage.spellName());

        Ac alch = new Ac(T0, null, Ai.CONSUMPTION, Aj.GENERIC,
            "", "Magic", true, Arrays.asList(new Ab(561, "Nature rune", -1L, 100, -100L),
                new Ab(554, "Fire rune", -5L, 5, -25L)), Bd.CONFIRMED, "fixture", null);
        alch.setActionKind(Au.CAST);
        alch.ahu(Bb.of("High Level Alchemy"));
        assertEquals("a spell outside the combat table keeps its click", "High Level Alchemy", alch.spellName());
    }

    private static Am engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Am(deltas ->
        {
            List<Ab> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int unit = delta.getKey() == 1359 ? 7_202 : 100;
                flows.add(new Ab(delta.getKey(), NAMES.get(delta.getKey()), delta.getValue(), unit,
                    delta.getValue() * unit, Av.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import org.junit.Test;
import static org.junit.Assert.*;

/** The journal's receipts are superseded by a measured Check, one weapon at a time. */
public class ChargeEstimateJournalTest
{
    @Test
    public void aMeasuredCheckClearsItsWeaponsPendingEstimates()
    {
        ChargeEstimateJournal journal = new ChargeEstimateJournal();
        journal.record("s1", "target", "Crystal bow", "tx1", 23962, 200L);
        journal.record("s2", "target", "Tome of fire", "tx2", 20718, 20L);
        assertEquals(1, journal.receipts("s1", "target", 23962).size());

        journal.clearTarget("s1", "target");
        assertTrue("the checked weapon's estimate receipts are gone",
            journal.receipts("s1", "target", 23962).isEmpty());
        assertEquals("another session stays untouched", 1,
            journal.receipts("s2", "target", 20718).size());
    }
}

package com.gpmanager;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.*;

/** Focused contracts for automatic charge estimates and Check reconciliation. */
public class ChargeEstimateReconciliationTest
{
    private static final long T0 = 10_000L;

    @Test
    public void estimatedUsageBooksLikelyCostAndKeepsComponentJournal()
    {
        Am engine = engine();
        engine.rm(T0);

        Ac receipt = engine.mn("slot-a", "seas",
            Au.CAST, flows(
                flow(ItemID.DEATHRUNE, "Death rune", -2L, 100),
                flow(ItemID.CHAOSRUNE, "Chaos rune", -2L, 50)), T0 + 1L);

        assertNotNull(receipt);
        assertEquals(Bd.LIKELY, receipt.getConfidence());
        assertEquals("Estimated", receipt.getExplanation());
        assertEquals(-300L, receipt.getNet());
        assertEquals(2L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.DEATHRUNE));
        assertEquals(2L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.CHAOSRUNE));
    }

    @Test
    public void checkShrinksEstimatesAtCapturedPricesAndBooksOnlyMeasuredRemainder()
    {
        Am engine = engine();
        engine.rm(T0);
        Ac estimate = engine.mn("slot-a", "seas",
            Au.CAST, flows(
                flow(ItemID.DEATHRUNE, "Death rune", -3L, 100),
                flow(ItemID.CHAOSRUNE, "Chaos rune", -1L, 50),
                flow(ItemID.FIRERUNE, "Fire rune", -10L, 5),
                new Ab(ItemID.COINS, "Coins", -20L, 1, -20L, Av.FACE_VALUE)), T0 + 1L);

        Cm delta = new Cm(Ar.V.TRIDENT_SEAS,
            Arrays.asList(new Cm.ComponentDelta(ItemID.DEATHRUNE, -2L),
                new Cm.ComponentDelta(ItemID.CHAOSRUNE, -3L),
                new Cm.ComponentDelta(ItemID.FIRERUNE, -10L),
                new Cm.ComponentDelta(ItemID.COINS, -20L)));
        Ac measured = engine.mj(delta, "Trident of the seas",
            flows(
                flow(ItemID.DEATHRUNE, "Death rune", -2L, 100),
                flow(ItemID.CHAOSRUNE, "Chaos rune", -3L, 50),
                flow(ItemID.FIRERUNE, "Fire rune", -10L, 5),
                new Ab(ItemID.COINS, "Coins", -20L, 1, -20L, Av.FACE_VALUE)),
            T0 + 2L, "slot-a");

        assertNotNull(measured);
        assertEquals(2L, estimate.quantity(ItemID.DEATHRUNE, false));
        assertEquals(100, estimate.getFlows().get(0).unitPrice);
        assertEquals(1L, estimate.quantity(ItemID.CHAOSRUNE, false));
        assertEquals(Bd.CONFIRMED, estimate.getConfidence());
        assertEquals("Confirmed", estimate.getExplanation());
        assertEquals(2L, measured.quantity(ItemID.CHAOSRUNE, false));
        assertEquals(0L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.DEATHRUNE));
        assertEquals(0L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.CHAOSRUNE));
    }

    @Test
    public void manualCorrectionSurvivesReconciliationWithoutRepricing()
    {
        Am engine = engine();
        engine.rm(T0);
        Ac estimate = engine.mn("slot-a", "seas",
            Au.CAST, Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -3L, 100)),
            T0 + 1L);
        assertTrue(engine.getActiveSession().qi(estimate.getId(),
            Ah.COST, T0 + 2L, "Owner decision"));

        Cm delta = new Cm(Ar.V.TRIDENT_SEAS,
            Collections.singletonList(new Cm.ComponentDelta(ItemID.DEATHRUNE, -2L)));
        Ac measured = engine.mj(delta, "Trident of the seas",
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -2L, 100)), T0 + 3L, "slot-a");

        assertNull(measured);
        assertEquals(Ah.COST, estimate.getCorrection());
        assertEquals(3L, estimate.quantity(ItemID.DEATHRUNE, false));
        assertEquals(100, estimate.getFlows().get(0).unitPrice);
    }

    @Test
    public void estimatesCannotReconcileAcrossSessions()
    {
        Am engine = engine();
        engine.rm(T0);
        Ac old = engine.mn("slot-a", "seas",
            Au.CAST, Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -2L, 100)),
            T0 + 1L);
        String oldSession = engine.getActiveSession().getId();
        engine.ajl("Custom", Cx.GENERAL, T0 + 2L);

        Cm delta = new Cm(Ar.V.TRIDENT_SEAS,
            Collections.singletonList(new Cm.ComponentDelta(ItemID.DEATHRUNE, -2L)));
        Ac measured = engine.mj(delta, "Trident of the seas",
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -2L, 100)), T0 + 3L, "slot-a");

        assertNotNull(measured);
        assertEquals(2L, old.quantity(ItemID.DEATHRUNE, false));
        assertEquals(2L, measured.quantity(ItemID.DEATHRUNE, false));
        assertEquals(0L, ChargeProbes.adp(engine.chargeEstimateJournal, oldSession,
            "slot-a", "seas", ItemID.DEATHRUNE));
    }

    @Test
    public void lifecycleResetClearsTransientEstimates()
    {
        Am engine = engine();
        engine.rm(T0);
        engine.mn("slot-a", "seas", Au.CAST,
            Collections.singletonList(flow(ItemID.DEATHRUNE, "Death rune", -1L, 100)), T0 + 1L);
        engine.acu(T0 + 2L);
        assertEquals(0L, ChargeProbes.adp(engine.chargeEstimateJournal, 
            engine.getActiveSession().getId(), "slot-a", "seas", ItemID.DEATHRUNE));
    }

    private static Am engine()
    {
        return new Am(deltas -> Collections.emptyList(),
            new TransactionClassifier(), new GpManagerConfig() {});
    }

    private static Ab flow(int id, String name, long quantity, int unit)
    {
        return new Ab(id, name, quantity, unit, quantity * unit, Av.GRAND_EXCHANGE);
    }

    private static List<Ab> flows(Ab... values)
    {
        return Arrays.asList(values);
    }

    private static List<Ab> tridentLosses(long death)
    {
        return flows(flow(ItemID.DEATHRUNE, "Death rune", death, 100),
            flow(ItemID.CHAOSRUNE, "Chaos rune", death, 50),
            flow(ItemID.FIRERUNE, "Fire rune", death * 5L, 5),
            new Ab(ItemID.COINS, "Coins", death * 10L, 1, death * 10L,
                Av.FACE_VALUE));
    }
}

package com.gpmanager;

import java.lang.reflect.Proxy;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * A widget-target click carries the target as the clicked widget and the item in hand as the
 * client's selected widget. A load arms in either order, against the weapon's own slot.
 */
public class ChargeLoadArmingTest
{
    private static final int BLOWPIPE_SLOT = 5;
    private static final int SCALES_SLOT = 9;

    private static Widget item(int itemId, int slot)
    {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[] {Widget.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getItemId": return itemId;
                    case "getIndex": return slot;
                    case "getId": return InterfaceID.Inventory.ITEMS;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        return null;
                }
            });
    }

    private static Client selecting(Widget selected)
    {
        return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getSelectedWidget": return selected;
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
    }

    static MenuOptionClicked click(MenuAction action, String option, Widget clicked)
    {
        MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
            new Class<?>[] {MenuEntry.class}, (proxy, method, args) ->
            {
                switch (method.getName())
                {
                    case "getOption": return option;
                    case "getTarget": return "";
                    case "getType": return action;
                    case "getWidget": return clicked;
                    case "getItemId": return clicked == null ? -1 : clicked.getItemId();
                    case "getParam0": return clicked == null ? -1 : clicked.getIndex();
                    case "getParam1": return clicked == null ? -1 : clicked.getId();
                    default:
                        if (method.getReturnType() == boolean.class) return false;
                        if (method.getReturnType() == int.class) return 0;
                        if (method.getReturnType() == long.class) return 0L;
                        return null;
                }
            });
        return new MenuOptionClicked(entry);
    }

    private static Am engine()
    {
        return new Am(deltas -> Collections.emptyList(), new TransactionClassifier(), new GpManagerConfig() {});
    }

    private static ChargeIntake intake(Client client, Am engine)
    {
        return new ChargeIntake(client, null, new GpManagerConfig() {}, engine, null)
        {
            @Override
            String itemName(int itemId)
            {
                return itemId == ItemID.SNAKEBOSS_SCALE ? "Zulrah's scales" : null;
            }
        };
    }

    private static final String BLOWPIPE_IDENTITY = (InterfaceID.Inventory.ITEMS >>> 16) + ":" + BLOWPIPE_SLOT + ":"
        + ItemID.TOXIC_BLOWPIPE_LOADED + ":" + Ar.V.V1b.name();

    @Test
    public void scalesUsedOnTheBlowpipeArmTheLoad()
    {
        Am engine = engine();
        Widget blowpipe = item(ItemID.TOXIC_BLOWPIPE_LOADED, BLOWPIPE_SLOT);
        Widget scales = item(ItemID.SNAKEBOSS_SCALE, SCALES_SLOT);
        intake(selecting(scales), engine).lc(
            click(MenuAction.WIDGET_TARGET_ON_WIDGET, "Use", blowpipe), "");
        assertEquals(Ar.V.V1b, (engine.eb.peek(Eb.CL) == null ? null : engine.eb.peek(Eb.CL).v));
        assertEquals("the item in hand is the source", ItemID.SNAKEBOSS_SCALE,
            engine.eb.item(Eb.CL));
        assertEquals("the weapon's own slot", BLOWPIPE_IDENTITY, (engine.eb.peek(Eb.CL) == null ? null : engine.eb.peek(Eb.CL).id));
    }

    @Test
    public void theBlowpipeUsedOnScalesArmsTheSameLoad()
    {
        Am engine = engine();
        Widget blowpipe = item(ItemID.TOXIC_BLOWPIPE_LOADED, BLOWPIPE_SLOT);
        Widget scales = item(ItemID.SNAKEBOSS_SCALE, SCALES_SLOT);
        intake(selecting(blowpipe), engine).lc(
            click(MenuAction.WIDGET_TARGET_ON_WIDGET, "Use", scales), "");
        assertEquals(Ar.V.V1b, (engine.eb.peek(Eb.CL) == null ? null : engine.eb.peek(Eb.CL).v));
        assertEquals(ItemID.SNAKEBOSS_SCALE, engine.eb.item(Eb.CL));
        assertEquals("the identity follows the weapon, not the clicked scales", BLOWPIPE_IDENTITY,
            (engine.eb.peek(Eb.CL) == null ? null : engine.eb.peek(Eb.CL).id));
    }

    @Test
    public void anUnrelatedItemOrPlainClickArmsNothing()
    {
        Am engine = engine();
        Widget blowpipe = item(ItemID.TOXIC_BLOWPIPE_LOADED, BLOWPIPE_SLOT);
        intake(selecting(item(ItemID.BIG_BONES, 2)), engine).lc(
