        // Respawn with the coins for the fee (coins are kept on death in this fixture).
        engine.yz();
        assertNull(engine.adj(gear(0L, 0L, 150_000L, 0L), 4_000L));
        engine.setBaseline(gear(0L, 0L, 150_000L, 0L));

