        // The returned gear is an uncounted transfer row, not revenue.
        List<Ac> rows = engine.getActiveSession().getTransactions();
        Ac recovered = null;
        for (Ac row : rows)
        {
            if ("Death reclaim: items recovered".equals(row.getNote()))
            {
