    private static long flow(Ac transaction, int itemId)
    {
        for (Ab itemFlow : transaction.getFlows())
        {
            if (itemFlow.itemId == itemId)
            {
                return itemFlow.valueDelta;
            }
        }
        return 0L;
    }

    /** Establish exact known coverage for an item (schema-106 tracked basis). */
    private static void gain(Am engine, int item, long quantity, long value, long at)
    {
        engine.getActiveSession().kf(new Ac(at, null,
            Ai.GAIN, Aj.GENERIC, "", "Loot", true,
            Collections.singletonList(new Ab(item, "Nature rune", quantity,
                (int) (quantity > 0L ? value / quantity : 0L), value,
                Av.GRAND_EXCHANGE)),
            Bd.CONFIRMED, "", null), 500);
    }

    private static int countCounted(Am engine)
    {
        int counted = 0;
        for (Ac transaction : engine.getActiveSession().getTransactions())
        {
            if (transaction != null && transaction.isCounted())
            {
                counted++;
            }
        }
        return counted;
    }

    private static void noteGe(Am engine, Bj ledger, int slot,
        GrandExchangeOfferState state, int itemId, int totalQuantity, int quantityTraded, int price,
        int spent, long at)
    {
        Bj.Transition transition = ledger.observe(
            new Bj.Snapshot(slot, state, itemId, totalQuantity, quantityTraded, price, spent))
            .orElse(null);
        if (transition != null)
        {
            engine.abh(transition, itemName(itemId), at);
        }
    }

    /** The owner's batch inventory with the seven items at five each. */
    private static Map<Integer, Long> ownerBatchInventory(long coins)
    {
        Map<Integer, Long> held = inventory(COINS, coins);
        for (int item : OWNER_BATCH_ITEMS)
        {
            held.put(item, 5L);
        }
        return held;
    }

    /** Place the owner's seven sell offers and capture each placement principal. */
    private static void placeOwnerBatch(Am engine, Bj ledger,
        Map<Integer, Long> held, long now, boolean terminal)
    {
        for (int slot = 0; slot < OWNER_BATCH_ITEMS.length; slot++)
        {
            int item = OWNER_BATCH_ITEMS[slot];
            noteGe(engine, ledger, slot, SELLING, item, 5, 0, OWNER_BATCH_LISTED[slot], 0,
                now + slot * 2_000L);
            held.put(item, 0L);
            settle(engine, held, now + slot * 2_000L + 200L);
            if (terminal)
            {
                completeOwnerSale(engine, ledger, slot, now + slot * 2_000L + 1_000L);
            }
        }
    }

    /** Feed the owner's terminal SOLD evidence for every offer. */
    private static void completeOwnerBatch(Am engine, Bj ledger, long now)
    {
        for (int slot = 0; slot < OWNER_BATCH_ITEMS.length; slot++)
        {
            completeOwnerSale(engine, ledger, slot, now + slot * 1_000L);
        }
    }

    private static void completeOwnerSale(Am engine, Bj ledger, int slot,
        long at)
    {
        noteGe(engine, ledger, slot, SOLD, OWNER_BATCH_ITEMS[slot], 5, 5, OWNER_BATCH_LISTED[slot],
            (int) OWNER_BATCH_EXECUTION[slot], at);
    }

    /** The exact owner-batch accounting every ordering must converge to. */
    private static void assertOwnerBatchSettled(Am engine, long now)
    {
        Map<Integer, Integer> slotByItem = ownerBatchSlots();
        long grossTotal = 0L;
        long taxTotal = 0L;
        long receivedTotal = 0L;
        int rows = 0;
        for (Bi.Row row : engine.ub())
        {
            Integer slot = slotByItem.get(row.itemId);
            if (slot == null)
            {
                continue;
            }
            rows++;
            assertEquals("Received is the actual after-tax cash",
                OWNER_BATCH_RECEIVED[slot], row.observedSettlementGp);
            assertEquals("the actual tax is decomposed, never booked",
                -OWNER_BATCH_TAX[slot], row.settlementAdjustmentGp);
            assertEquals(OWNER_BATCH_TAX[slot], row.inferredGeTaxGp);
            assertEquals(OWNER_BATCH_EXECUTION[slot], MarketFacts.realizedGrossGp(MarketFacts.record(engine, row)));
            assertEquals("the actual after-tax unit value is exact",
                OWNER_BATCH_RECEIVED[slot] / 5L, row.receivedEachGp);
            assertEquals(Bi.Coverage.FULLY_UNKNOWN, row.coverage);
            assertEquals(Bi.Lifecycle.REALIZED, row.lifecycle);
            assertFalse(row.manualFinancialResult);
            if (OWNER_BATCH_TAX[slot] > 0L)
            {
                assertTrue("every taxed unknown-basis receipt books exactly its proven tax",
                    row.knownCostOnly);
                assertEquals(-OWNER_BATCH_TAX[slot], row.realizedResultGp);
            }
            else
            {
                assertFalse("the exempt sale is never KNOWN_COST_ONLY", row.knownCostOnly);
                assertEquals(0L, row.realizedResultGp);
            }
            grossTotal += MarketFacts.realizedGrossGp(MarketFacts.record(engine, row));
            taxTotal += -row.settlementAdjustmentGp;
            receivedTotal += row.observedSettlementGp;
        }
        assertEquals(7, rows);
        assertEquals(OWNER_BATCH_GROSS_TOTAL, grossTotal);
        assertEquals(OWNER_BATCH_TAX_TOTAL, taxTotal);
        assertEquals(OWNER_BATCH_RECEIVED_TOTAL, receivedTotal);
        assertEquals("unknown bank stock drops by exactly the proven batch tax", -480L,
            engine.getMetrics(now).net);
        for (Ac transaction : engine.getActiveSession().getTransactions())
        {
            assertFalse("no uncounted review row may exist for an exact batch: " + transaction,
                Eh.aal(transaction));
            assertFalse("no synthetic Coins fee row may exist: " + transaction,
                transaction != null && transaction.isCounted()
                    && transaction.tm() == Ai.TRADE
                    && transaction.getFlows().size() == 1
                    && transaction.getFlows().get(0).itemId == COINS);
            if (transaction != null && transaction.isCounted()
                && transaction.tm() == Ai.TRADE)
            {
                assertEquals("one counted settlement per sale, each exactly its accepted tax",
                    -OWNER_BATCH_TAX[slotByItem.get(transaction.getFlows().get(0).itemId)],
                    transaction.getNet());
            }
        }
    }

    private static Map<Integer, Integer> ownerBatchSlots()
    {
        Map<Integer, Integer> slotByItem = new HashMap<>();
        for (int slot = 0; slot < OWNER_BATCH_ITEMS.length; slot++)
        {
            slotByItem.put(OWNER_BATCH_ITEMS[slot], slot);
        }
        return slotByItem;
    }

    private static int reviewCount(Am engine)
    {
        int reviews = 0;
        for (Ac transaction : engine.getActiveSession().getTransactions())
        {
            if (Eh.aal(transaction))
            {
                reviews++;
            }
        }
        return reviews;
    }

    private static int countUncertainCoinRows(Am engine)
    {
        int rows = 0;
        for (Ac transaction : engine.getActiveSession().getTransactions())
        {
            if (transaction != null && transaction.tm() == Ai.UNCERTAIN
                && transaction.getFlows().size() == 1
                && transaction.getFlows().get(0).itemId == COINS)
            {
                rows++;
            }
        }
        return rows;
    }

    private static String itemName(int itemId)
    {
        switch (itemId)
        {
            case RUNE: return "Nature rune";
            case COINS: return "Coins";
            case CHAOS_RUNE: return "Chaos rune";
            case OAK_LOGS: return "Oak logs";
            case DIAMOND_BOLTS_E: return "Diamond bolts (e)";
            case SAPPHIRE_DRAGON_BOLTS_E: return "Sapphire dragon bolts (e)";
            case DRAGONFRUIT: return "Dragonfruit";
            case TEAK_PLANK: return "Teak plank";
            case BOLT_OF_LINEN: return "Bolt of linen";
            case ANGLERFISH: return "Anglerfish";
            case COOKED_KARAMBWAN: return "Cooked karambwan";
            case SHARK: return "Shark";
            case COOKED_CHICKEN: return "Cooked chicken";
            default: return "Item " + itemId;
        }
    }

    /** Production login priming: feed the stable baseline until the engine is ready to book. */
    private static void prime(Am engine, Map<Integer, Long> inventory, long now)
    {
        Cc snapshot = new Cc(inventory);
        for (int i = 0; i < 20 && EngineProbe.isBaselinePriming(engine); i++)
        {
            engine.adj(snapshot, now + i * 600L);
        }
    }

    private static Ac settle(Am engine, Map<Integer, Long> next, long now)
    {
        engine.yz();
        Cc snapshot = new Cc(next);
        Ac result = null;
        for (int i = 0; i < 3; i++)
        {
            Ac settled = engine.adj(snapshot, now + i * 600L);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Map<Integer, Long> inventory(Object... pairs)
    {
        Map<Integer, Long> map = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2)
        {
            map.put((Integer) pairs[i], (Long) pairs[i + 1]);
        }
        return map;
    }

    private static Am engine()
    {
        return engine(6L);
    }

    /** One frozen reference unit for every non-coin item (the schema-106 test default is 6). */
    private static Am engine(long unitPrice)
    {
        return pricedEngine(id -> unitPrice);
    }

    /** The owner's true frozen references per item, as shown in the reference screenshots. */
    private static Am ownerEngine()
    {
        return pricedEngine(GeCustodyPersistenceTest::ownerReference);
    }

    private static long ownerReference(int itemId)
    {
        switch (itemId)
        {
            case CHAOS_RUNE: return 104L;
            case OAK_LOGS: return 41L;
            case DIAMOND_BOLTS_E: return 157L;
            case SAPPHIRE_DRAGON_BOLTS_E: return 2_802L;
            // The owner's seven-sale batch frozen references, as persisted live.
            case DRAGONFRUIT: return 750L;
            case TEAK_PLANK: return 860L;
            case BOLT_OF_LINEN: return 404L;
            case ANGLERFISH: return 1_634L;
            case COOKED_KARAMBWAN: return 410L;
            case SHARK: return 994L;
            case COOKED_CHICKEN: return 66L;
            default: return 6L;
        }
    }

    private static Am pricedEngine(java.util.function.IntToLongFunction unitOf)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 1; }
            @Override public boolean keepTransferAuditRows() { return true; }
        };
        return new Am(deltas ->
        {
            List<Ab> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                long unit = id == COINS ? 1L : unitOf.applyAsLong(id);
                flows.add(new Ab(id, itemName(id), delta.getValue(), (int) unit,
                    delta.getValue() * unit,
                    id == COINS ? Av.FACE_VALUE : Av.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Owner smoke (G2 re-test): a collect held for exact attribution must resolve on game ticks, not
 * only when a later inventory change happens to settle. The hold is transient, so waiting for an
 * unrelated movement left the cash invisible and lost it on logout.
 */
public class GeCustodyTickTest
{
    private static final int COINS = ItemID.COINS;
    private static final int SHARK = ItemID.SHARK;
    private static final long T0 = 1_000_000_000_000L;
    private static final long RECEIVED = 29_280L - 570L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void heldCollectResolvesOnTheTickAfterItsWindowWithoutAnotherInventoryChange()
    {
        Map<Integer, Long> inventory = new HashMap<>();
        Am engine = engine();
        engine.ajl("Trading", Cx.AUTO, T0);
        inventory.put(COINS, 1_000_000L);
        inventory.put(SHARK, 60L);
        engine.setBaseline(new Cc(inventory));
        Bj ledger = new Bj();
        long t = T0 + 10_000L;
        // Two identical sold offers: one collect's cash matches either, so it is a tie.
        offer(engine, ledger, 0, SELLING, 0, 0, t);
        offer(engine, ledger, 1, SELLING, 0, 0, t + 50L);
        inventory.put(SHARK, 0L);
        settle(engine, inventory, t + 100L);
        offer(engine, ledger, 0, SOLD, 30, 29_280, t + 200L);
        offer(engine, ledger, 1, SOLD, 30, 29_280, t + 250L);

        engine.abg(t + 10_000L);
        inventory.put(COINS, 1_000_000L + RECEIVED);
        settle(engine, inventory, t + 10_000L);
        assertEquals("the tied cash is held for slot evidence", RECEIVED,
            EngineProbe.pendingSettlementCash(engine.geCustody));
        assertEquals(0, reviewRows(engine));

        assertFalse("inside the window nothing is decided", engine.ajv(t + 10_600L));
        assertTrue("the first tick after the window resolves it", engine.ajv(t + 12_400L));
        assertEquals(0L, EngineProbe.pendingSettlementCash(engine.geCustody));
        assertTrue("a tie with no slot evidence fails closed visibly", reviewRows(engine) > 0);
        assertEquals("nothing is counted from an unproven tie", 0L, engine.getMetrics(t + 13_000L).net);
    }

    @Test
    public void pausedTrackingNeverBooksFromTheTick()
    {
        Am engine = engine();
        engine.ajl("Trading", Cx.AUTO, T0);
        engine.togglePause(T0 + 1_000L);
        assertFalse(engine.ajv(T0 + 2_000L));
    }

    private static int reviewRows(Am engine)
    {
        int count = 0;
        for (Ac transaction : engine.getActiveSession().getTransactions())
        {
            if (Eh.aal(transaction))
            {
                count++;
            }
        }
        return count;
    }

    private static void offer(Am engine, Bj ledger, int slot,
        GrandExchangeOfferState state, int traded, int spent, long at)
    {
        ledger.observe(new Bj.Snapshot(slot, state, SHARK, 30, traded, 978, spent))
            .ifPresent(transition -> engine.abh(transition, "Shark", at));
    }

    private static void settle(Am engine, Map<Integer, Long> inventory, long at)
    {
        engine.yz();
        Cc snapshot = new Cc(inventory);
        engine.adj(snapshot, at);
        engine.adj(snapshot, at + 1L);
    }

    private static Am engine()
    {
        return new Am(deltas ->
        {
            List<Ab> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int id = delta.getKey();
                long unit = id == COINS ? 1L : 978L;
                flows.add(new Ab(id, id == COINS ? "Coins" : "Shark", delta.getValue(), (int) unit,
                    delta.getValue() * unit,
                    id == COINS ? Av.FACE_VALUE : Av.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), new GpManagerConfig()
        {
            @Override
            public Db receiptRetentionDays()
            {
                return Db.DAYS_365;
            }

            @Override
            public int stabilizationTicks()
            {
                return 0;
            }
        });
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_BUY;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * C3a GE evidence ownership: the offer ledger is item/direction-scoped settlement evidence, never a
 * blanket MARKET hint. Stronger source evidence keeps its delta, terminal/cancel offer states never
 * explain a later movement, and account/profile plus destructive-reset boundaries clear the evidence.
 */
public class GeEvidenceOwnershipTest
{
    private static final int LOGS = 1519;
    private static final int SHARK = 385;
    private static final int COINS = 995;
    private static final long T0 = 1_000_000_000_000L;

    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    @Test
    public void realLootKeepsItsDeltaWhenARecentBuyForTheSameItemExists()
    {
        Am engine = engine();
        long now = T0;
        engine.ajl("Trading", Cx.AUTO, now);
        engine.setBaseline(new Cc(inventory(COINS, 100_000L)));

        Bj ledger = new Bj();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BOUGHT, SHARK, 5, 5, 800, 4_000, now + 600L);

        engine.zk(quantities(SHARK, 1L), 100, "Loot from Goblin", "Goblin");
        Ac loot = settle(engine, inventory(COINS, 100_000L, SHARK, 1L), now + 1_200L);

        assertNotNull(loot);
        assertEquals("real loot owns its delta over a recent GE buy of the same item",
            Ai.LOOT, loot.getType());
        assertEquals("Loot from Goblin", loot.getNote());
    }

    @Test
    public void passiveProgressCannotClaimAnUnrelatedItemDelta()
    {
        Am engine = engine();
        long now = T0;
        engine.ajl("Trading", Cx.AUTO, now);
        engine.setBaseline(new Cc(inventory(COINS, 100_000L)));

        Bj ledger = new Bj();
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 0, 800, 0, now);
        noteGe(engine, ledger, 0, BUYING, SHARK, 5, 2, 800, 1_600, now + 600L);

        Ac gain = settle(engine, inventory(COINS, 100_000L, LOGS, 1L), now + 1_200L);

        assertNotNull(gain);
        assertEquals(Ai.GAIN, gain.getType());
    }

    @Test
    public void passiveProgressAloneCannotClaimTheSameItemDelta()
    {
        Am engine = engine();
        long now = T0;
        engine.ajl("Trading", Cx.AUTO, now);
        engine.setBaseline(new Cc(inventory(COINS, 100_000L)));

        Bj ledger = new Bj();
