package com.gpmanager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Owner report 2026-09-28: 50 Chaos runes picked up in the same settle as one thrown Steel dart went
 * to an uncounted Review. A pickup with only a routine rune/ammo spend is a counted gain net of it.
 */
public class PickupWithRoutineSpendTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final int POUCH = 22538;
    private static final Map<Integer, String> NAMES = new HashMap<>();

    static
    {
        NAMES.put(562, "Chaos rune");
        NAMES.put(808, "Steel dart");
        NAMES.put(385, "Shark");
        NAMES.put(POUCH, "Coin pouch");
        NAMES.put(995, "Coins");
    }

    @Test
    public void openingCoinPouchesIsACountedGain()
    {
        Ac settled = settleFrom(POUCH, 2L, 995, 60L, POUCH, 0L);
        assertNotNull(settled);
        assertEquals("the coins count as income, not an uncounted Review",
            Ai.GAIN, settled.getType());
        assertTrue(settled.isCounted());
    }

    @Test
    public void aPickupWithADartThrownIsACountedGain()
    {
        Ac settled = settleFrom(808, 10L, 562, 50L, 808, 9L);
        assertNotNull(settled);
        assertEquals(Ai.GAIN, settled.getType());
        assertTrue("counted, never an uncounted Review", settled.isCounted());
        assertEquals("Net is the runes less the dart", 50L * 90L - 4L, settled.getNet());
    }

    @Test
    public void aPickupWithFoodEatenStaysReview()
    {
        Ac settled = settleFrom(385, 3L, 562, 50L, 385, 2L);
        assertNotNull(settled);
        assertEquals("food is not a routine combat spend", Ai.UNCERTAIN, settled.getType());
    }

    /** Baseline {first: firstQty}, then {gainId: gainQty, first: firstAfter}. */
    private static Ac settleFrom(int first, long firstQty, int gainId, long gainQty, int after, long afterQty)
    {
        Am engine = engine();
        engine.ajl("Nechryael", Cx.GENERAL, T0);
        Map<Integer, Long> held = new HashMap<>();
        held.put(first, firstQty);
        engine.setBaseline(new Cc(new HashMap<>(held)));
        held.put(gainId, gainQty);
        held.put(after, afterQty);
        engine.yz();
        Ac result = null;
        for (int i = 0; i < 3; i++)
        {
            Ac settled = engine.adj(new Cc(new HashMap<>(held)), T0 + 600L + i * 600L);
            if (settled != null)
            {
                result = settled;
            }
        }
        return result;
    }

    private static Am engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override
            public int stabilizationTicks()
            {
                return 1;
            }
        };
        return new Am(deltas ->
        {
            List<Ab> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> delta : deltas.entrySet())
            {
                int unit = delta.getKey() == 562 ? 90 : delta.getKey() == 808 ? 4 : 900;
                flows.add(new Ab(delta.getKey(), NAMES.get(delta.getKey()), delta.getValue(), unit,
                    delta.getValue() * unit, Av.GRAND_EXCHANGE));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Ground Items filtering is presentation only. A live presentation filter can never change
 * canonical money, rollups or corrections. Bank-close burial remains an observed supply cost.
 */
public class PresentationFilterAccountingIsolationEngineTest
{
    private Am engine()
    {
        GpManagerConfig config = new GpManagerConfig() {
            public int stabilizationTicks() { return 2; }
            public boolean keepTransferAuditRows() { return true; }
            public Dl lootPresentationFilter() { return Dl.HIGHLIGHTED_LIST_ONLY; }
        };
        Am engine = new Am(deltas -> {
            List<Ab> flows = new ArrayList<>();
            deltas.forEach((id, quantity) -> flows.add(new Ab(id, "Bones", quantity, 35, quantity * 35L)));
            return flows;
        }, new TransactionClassifier(), config);
        engine.rm(1000L);
        return engine;
    }

    /** A Ground Items rule set that would show only feathers; bones are hidden from presentation. */
    private void onlyFeathers(Am engine)
    {
        engine.setContributionEligibility(new LootPresentationFilterService(new Bc(
            true, "Feather", "Bones", false)));
    }

    private Ac gain(Ab... flows)
    {
        return Tx.of(1600L, Ai.GAIN, Aj.GENERIC,
            "Pickup", true, Arrays.asList(flows));
    }

    @Test public void burialCallbackBeforeGameTickBankCloseMustNotLatchOldTransfer()
    {
        Am engine = engine();
        Cc bones = new Cc(Collections.singletonMap(526, 1L));
        engine.setBaseline(bones);
        engine.ze(6);
        engine.adj(bones, 1000L);
        engine.yz();
        engine.yu();
        engine.adj(Cc.empty(), 1600L);
        engine.adj(Cc.empty(), 2200L);
        Ac tx = engine.adj(Cc.empty(), 2800L);
        assertEquals(Ai.CONSUMPTION, tx.getType());
    }

    @Test public void hiddenItemsStillCountInNetAndInsights()
    {
        Am engine = engine();
        onlyFeathers(engine);
        engine.getActiveSession().kf(gain(new Ab(526, "Bones", 1L, 35, 35L)), 100);
        assertEquals(35L, engine.getMetrics(2800L).net);
    }

    @Test public void correctionsOperateOnTheWholeCanonicalRow()
    {
        Am engine = engine();
        onlyFeathers(engine);
        Ac tx = gain(new Ab(526, "Bones", 1L, 35, 35L),
            new Ab(314, "Feather", 1L, 10, 10L));
        engine.getActiveSession().kf(tx, 100);
        assertEquals(45L, engine.getMetrics(2800L).revenue);
        engine.getActiveSession().qi(tx.getId(), Ah.REVENUE, 3000L, "Manual correction");
        assertEquals(45L, engine.getMetrics(3100L).revenue);
    }

    @Test public void compactionFoldsExactRawValues()
    {
        Am engine = engine();
        onlyFeathers(engine);
        Ad session = engine.getActiveSession();
        session.kf(gain(new Ab(526, "Bones", 1L, 35, 35L)), 1);
        session.kf(gain(new Ab(526, "Bones", 1L, 35, 35L)), 1);
        assertTrue(session.compactedTransactionCount > 0L);
        assertEquals(70L, engine.getMetrics(2800L).net);
    }
}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.SkullIcon;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Charter E: NONE / SAFE_PVP_OR_MINIGAME / DANGEROUS_PVP precedence is fail-closed, context never
 * touches session identity, opponent names never persist by default, and best/worst/net follow
 * the correction-aware encounter summary. Offline only; live acceptance is owner-gated.
 */
public class PvpContextTest
{
    private static final int LMS_REGION = 13658;
    private static final int CASTLE_WARS_REGION = 9520;
    private static final int LUMBRIDGE_REGION = 12850;

    @Test
    public void knownDangerousContextsAreConfident()
    {
        assertEquals(Dh.DANGEROUS_PVP, Dh.classify(true, false, false, false, 0));
        assertEquals("attackable on a PvP world", Dh.DANGEROUS_PVP,
            Dh.classify(false, true, true, false, LUMBRIDGE_REGION));
        assertTrue(Dh.DANGEROUS_PVP.ws());
    }

    @Test
    public void positivelyIdentifiedSafeArenasWinOverEverything()
    {
        assertEquals(Dh.SAFE_PVP_OR_MINIGAME, Dh.classify(false, true, false, false, LMS_REGION));
        assertEquals(Dh.SAFE_PVP_OR_MINIGAME, Dh.classify(false, false, false, false, CASTLE_WARS_REGION));
        assertEquals("PvP Arena worlds are safe PvP", Dh.SAFE_PVP_OR_MINIGAME,
            Dh.classify(false, true, true, true, LUMBRIDGE_REGION));
        assertEquals("a safe arena inside conflicting dangerous signals stays safe", Dh.SAFE_PVP_OR_MINIGAME,
            Dh.classify(true, true, true, false, LMS_REGION));
    }

    @Test
    public void noSignalsIsNone()
    {
        assertEquals(Dh.NONE, Dh.classify(false, false, false, false, LUMBRIDGE_REGION));
        assertEquals("unknown region with no signals", Dh.NONE, Dh.classify(false, false, false, false, 0));
    }

    @Test
    public void conflictingOrInsufficientSignalsNeverBecomeDangerous()
    {
        assertEquals("PvP world bank safe zone (no attackable orb)", Dh.NONE,
            Dh.classify(false, false, true, false, LUMBRIDGE_REGION));
        assertEquals("attackable orb without a world/Wilderness fact is ambiguous", Dh.NONE,
            Dh.classify(false, true, false, false, LUMBRIDGE_REGION));
        assertEquals("orb alone with an unknown region", Dh.NONE, Dh.classify(false, true, false, false, 0));
    }

    @Test
    public void manualPkTripSessionIsIndependentOfContextDetection()
    {
        Am engine = engine();
        engine.rm(1_000L);
        engine.ajl("PK Trip", Cx.PK, 2_000L);
        String tripId = engine.getActiveSession().getId();

        // Aj is bookkeeping only: it never creates, renames or splits the manual session.
        engine.zn(Collections.singletonMap(4151, 1L), 10, "Player kill", 3_000L);
        engine.zo("Player death", 4_000L);

        assertEquals(tripId, engine.getActiveSession().getId());
        assertEquals("PK Trip", engine.getActiveSession().getName());
        assertEquals(Cx.PK, engine.getActiveSession().getMode());
        assertEquals(2, engine.getActiveSession().getPkEncounters().size());
        assertEquals("no automatic session was spawned", 0, engine.getHistory().size());
    }

    @Test
    public void opponentNamesNeverPersistByDefaultAndDeathsNeverCarryThem()
    {
        Am engine = engine();
        engine.rm(1_000L);
        engine.zn(Collections.emptyMap(), 10, "Player kill", 2_000L);
        engine.zo("Player death", 3_000L);
        for (Bx encounter : engine.getActiveSession().getPkEncounters())
        {
            assertFalse(encounter.label.contains(":"));
        }
        assertEquals(Be.DEATH, engine.getActiveSession().getPkEncounters().get(1).getType());
    }

    @Test
    public void correctionsRecomputeBestKillWorstDeathAndNet()
    {
        Am engine = engine();
        engine.rm(1_000L);
        engine.setBaseline(Cc.empty());

        engine.zn(Collections.singletonMap(4151, 1L), 10, "Player kill", 2_000L);
        Ac loot = settle(engine, Collections.singletonMap(4151, 1L), 2_600L);
        assertNotNull(loot);
        assertEquals(Ai.PK_LOOT, loot.getType());
        Dt before = engine.getActiveSession().ava();
        assertEquals(1_000_000L, before.bestKill);
        assertEquals(1_000_000L, before.net);

        assertTrue(engine.qi(loot.getId(), Ah.IGNORE, 3_000L, "not mine"));
        Dt excluded = engine.getActiveSession().ava();
        assertEquals("an excluded kill receipt leaves the encounter but not its value", 1, excluded.kills);
        assertEquals(0L, excluded.bestKill);
        assertEquals(0L, excluded.net);

        assertTrue(engine.qi(loot.getId(), Ah.REVENUE, 3_500L, "counted again"));
        assertEquals(1_000_000L, engine.getActiveSession().ava().bestKill);

        engine.zo("Player death", 4_000L);
        Dt afterDeath = engine.getActiveSession().ava();
        assertEquals(1, afterDeath.deaths);
        assertEquals("a death without a settled loss is not a guessed worst death", 0L, afterDeath.largestDeathLoss);
    }

    @Test
    public void relogKeepsEncountersOnTheSameOwner()
    {
        Am engine = engine();
        engine.rm(1_000L);
        engine.zn(Collections.emptyMap(), 10, "Player kill", 2_000L);
        engine.acu(3_000L);
        engine.resume(4_000L, Ed.LIFECYCLE);
        engine.zo("Player death", 5_000L);
        assertEquals(1, engine.getActiveSession().ava().kills);
        assertEquals(1, engine.getActiveSession().ava().deaths);
        assertEquals("relog never closes the owner", 0L, engine.getActiveSession().endedAtEpochMillis);
    }

    private static Ac settle(Am engine, Map<Integer, Long> quantities, long now)
    {
        engine.yz();
        Cc snapshot = new Cc(quantities);
        Ac result = engine.adj(snapshot, now);
        return result != null ? result : engine.adj(snapshot, now + 1L);
    }

    private static Am engine()
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public int stabilizationTicks() { return 0; }
        };
        return new Am(deltas ->
        {
            List<Ab> flows = new ArrayList<>();
            deltas.forEach((id, qty) -> flows.add(new Ab(id, "Item " + id, qty, 1_000_000, qty * 1_000_000L)));
            return flows;
        }, new TransactionClassifier(), config);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Receipt retention compacts individually inspectable detail while preserving exact totals
 * and correction-aware metrics.
 */
public class ReceiptRetentionTest
{
    static
    {
        JsonCodec.bind(new com.google.gson.Gson());
    }

    private static final long DAY = 86_400_000L;

    private static final GpManagerConfig CONFIG = new GpManagerConfig()
    {
        @Override
        public int maxHistorySessions()
        {
            return 2_000;
        }

        @Override
        public Db receiptRetentionDays()
        {
            return Db.DAYS_90;
        }
    };

    @Test
    public void compactsRowsStrictlyOlderThanTheCutoffByTransactionTimeAcrossOwners()
    {
        // Section L: the cutoff is transaction time, whether the owner is closed or still active.
        long now = 100L * DAY + 12L * 60L * 60L * 1_000L;
        long cutoff = now - 30L * DAY;
        Ad boundary = new Ad("Boundary", cutoff - 10_000L);
        boundary.kf(receipt(cutoff, 100L), 10);
        boundary.close(cutoff + 1_000L);
        Ad old = new Ad("Old", cutoff - 10_000L);
        old.kf(receipt(cutoff - 1L, 200L), 10);
        old.close(cutoff + 2_000L);
        Ad active = new Ad("Active", cutoff - 2L * DAY);
        active.kf(receipt(cutoff - DAY, 300L), 10);
        active.kf(receipt(cutoff + DAY, 50L), 10);

        Am engine = engine();
        engine.restore(new SavedState(null, null, false, Arrays.asList(boundary, old, old, active)), now);

        assertEquals(2, engine.pg(30, now));
        assertEquals("a row exactly at the cutoff is retained", 1, boundary.getTransactions().size());
        assertTrue(old.getTransactions().isEmpty());
        assertEquals(1L, old.compactedTransactionCount);
        assertEquals(200L, old.metrics(now).revenue);
        assertEquals("only the active owner's overdue row folds", 1, active.getTransactions().size());
        assertEquals(350L, active.metrics(now).revenue);
        assertEquals(0, engine.pg(30, now));
        assertEquals(0, engine.pg(0, now));
    }

    @Test
    public void derivedPendingClaimIdKeepsItsOriginAuditRowRetained()
    {
        long now = 400L * DAY;
        Ad session = new Ad("Loot origin", now - 200L * DAY);
        Ac audit = receipt(now - 200L * DAY + 1_000L, 0L);
        session.kf(audit, 10);
        session.close(now - 200L * DAY + 2_000L);

        SavedState state = new SavedState(null, null, false, Collections.singletonList(session));
        state.setPendingClaims(Collections.singletonList(new SavedState.By(
            audit.getId() + "#2", net.runelite.api.gameval.ItemID.WILDY_LOOT_KEY1, 1L,
            audit.timestampEpochMillis)));

        Am engine = engine();
        engine.restore(state, now);

        assertEquals("a multi-key claim protects the shared origin audit row", 1,
            session.getTransactions().size());
        assertTrue(engine.getPendingClaims().get(0).getClaimId().endsWith("#2"));
        assertEquals(0, engine.pg(90, now));
    }

    @Test
    public void compactionKeepsMetadataEncountersAndExactTotals()
    {
        long now = 400L * DAY;
        Ad session = new Ad("Favourite trip", now - 200L * DAY, Cx.PK);
        java.util.Collections.addAll(session.tags, "boss", "pet");
        session.notes = "keep this note";
        session.setFavorite(true);
        session.setExcludedFromAverages(true);

        session.kf(receipt(now - 200L * DAY + 1_000L, 100L), 10);
        session.kf(receipt(now - 200L * DAY + 61_000L, 250L), 10);
        session.kf(receipt(now - 200L * DAY + 62_500L, -40L), 10);
        Bx encounter = session.ke(Be.KILL, now - 200L * DAY + 62_000L,
            "Player kill", null, "observed encounter");
        session.ll(session.getTransactions().get(1).getId(), encounter.getId(), false);
        session.close(now - 200L * DAY + 120_000L);

        Bu before = session.metrics(now);
        Dt pkBefore = session.ava();
        Am engine = engine();
        engine.restore(new SavedState(null, null, false, Collections.singletonList(session)), now);

        assertEquals("current-schema restore already compacted the overdue rows", 0,
            engine.pg(90, now));

        assertTrue(session.getTransactions().isEmpty());
        assertEquals(3L, session.compactedTransactionCount);
        assertEquals("boss, pet", String.join(", ", session.tags));
        assertEquals("keep this note", session.notes);
        assertTrue(session.favorite);
        assertTrue(session.excludedFromAverages);
        assertEquals("detail beyond the receipt horizon is compacted", 0, session.getPkEncounters().size());
        assertEquals(Di.RETAINED_WINDOW,
            session.pkProjection.ud());
        assertEquals("compacted detail stays represented by exact counts",
            1, session.pkProjection.getKills());

        Bu after = session.metrics(now);
        assertEquals(before.revenue, after.revenue);
        assertEquals(before.costs, after.costs);
        assertEquals(before.net, after.net);
        assertEquals(350L, after.revenue);
        assertEquals(40L, after.costs);
        Dt pkAfter = session.ava();
        assertEquals(pkBefore.kills, pkAfter.kills);
        assertEquals(pkBefore.net, pkAfter.net);
        assertEquals(pkBefore.bestKill, pkAfter.bestKill);
    }

    @Test
    public void currentSchemaRestoreCompactsOverdueRowsWithoutWaitingForUtcRollover()
    {
        long now = 120L * DAY + 12L * 60L * 60L * 1_000L;
        Ad overdue = closedWithReceipt("Overdue", now - 120L * DAY - 1L, 750L);
        SavedState current = new SavedState(null, null, false, Collections.singletonList(overdue));
        current.setLastReceiptRetentionDayUtc(LocalDate.ofEpochDay(120L).toString());

        Am engine = engine();
        engine.restore(current, now);

        assertTrue(overdue.getTransactions().isEmpty());
        assertEquals(1L, overdue.compactedTransactionCount);
        assertEquals(750L, overdue.metrics(now).revenue);
        assertEquals(LocalDate.ofEpochDay(120L).toString(),
            engine.qm().getLastReceiptRetentionDayUtc());
    }

    @Test
    public void shippingRetentionWindowsAreBoundedAndUnknownReadsAs90Days()
    {
        assertEquals(Arrays.asList(30, 90, 180, 365), Arrays.asList(
            Db.DAYS_30.getDays(), Db.DAYS_90.getDays(),
            Db.DAYS_180.getDays(), Db.DAYS_365.getDays()));
        assertEquals(4, Db.values().length);
        for (Db period : Db.values())
        {
            assertFalse("no shipping window means retain forever", period.getDays() <= 0);
        }
    }

    private static Ad closedWithReceipt(String name, long endedAt, long value)
    {
        long start = Math.max(0L, endedAt - 10_000L);
        Ad session = new Ad(name, start);
        session.kf(receipt(start + 1_000L, value), 10);
        session.close(endedAt);
        return session;
    }

    private static Ac receipt(long timestamp, long value)
    {
        return Tx.of(timestamp, value < 0L ? Ai.CONSUMPTION : Ai.LOOT,
            Aj.LOOT, "receipt", true, Collections.singletonList(new Ab(995, "Coins",
                value < 0L ? -1L : 1L, (int) Math.min(Integer.MAX_VALUE, Math.abs(value)), value)));
    }

    private static Am engine()
    {
        return new Am(deltas -> Collections.emptyList(), new TransactionClassifier(), CONFIG);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.function.LongSupplier;
import org.junit.Assume;
import org.junit.Test;
import org.junit.experimental.categories.Category;

/**
 * Release pass 2026-09-28: timing budget on a heavy profile (a running Grind at the 2,000 detailed
 * receipts the default keeps, 300 finished Grinds). Dev-only; runs when GP_PERF is set:
 * {@code GP_PERF=1 ./gradlew test --tests 'com.gpmanager.ReleasePerfTest'}. Prints median/p99.
 */
@Category(PerformanceBudget.class)
public class ReleasePerfTest
{
    private static final long T0 = 1_700_000_000_000L;
    private static final Random RANDOM = new Random(20260928L);

    @Test
    public void heavyProfileStaysInsideTheFrameBudget() throws Exception
    {
        Assume.assumeTrue("set GP_PERF to run", System.getenv("GP_PERF") != null);
        Am engine = PresentationLifecycleTest.engine();
        for (int grind = 0; grind < 300; grind++)
        {
            Ad done = new Ad("Grind " + grind, T0 - (300 - grind) * 3_600_000L);
            for (int i = 0; i < 60; i++)
            {
                done.kf(receipt(done.startedAtEpochMillis + i * 1_000L), 2_000);
            }
            done.close(done.startedAtEpochMillis + 3_000_000L);
            engine.history.add(0, done);
        }
        engine.ajl("Greater Nechryael", Cx.GENERAL, T0);
        for (int i = 0; i < 2_000; i++)
        {
            engine.getActiveSession().kf(receipt(T0 + i * 1_800L), 2_000);
        }
        long now = T0 + 4_000_000L;

        List<Ac> all = engine.getActiveSession().getTransactions();
        report("Bp.transaction x2000", () -> all.stream().mapToLong(t -> Bp.transaction(t).costs).sum());
        report("Bp.costSplit x2000", () -> all.stream().mapToLong(t -> Bp.costSplit(t).supplies).sum());
        report("spellName x2000", () -> all.stream().mapToLong(t -> t.spellName().length()).sum());
        report("Ledger contributions x2000", () -> all.stream().mapToLong(t -> Af.project(t).size()).sum());
        report("session metrics", () -> engine.getActiveSession().metrics(now).net);
        int[] flip = {0};
        report("Live capture (cold)", () -> Ca.capture(engine, now,
            new Dz(false, null, flip[0]++ % 2, Bo.NONE, "", false, "")).net);
        report("Live capture (warm)", () -> Ca.capture(engine, now, Dz.NONE).net);
        report("Ledger capture", () -> Ao.capture(engine, now, Ao.Entry.current()).net);
        report("Grinds capture", () -> As.capture(engine, now, false, null).myGrinds.size());
        GpManagerConfig config = HudBuilderTest.config(true, 4);
        Cp builder = new Cp(config, null);
        De overlay = new De(builder, config);
        Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
        Ca snapshot = Ca.capture(engine, now, Dz.NONE);
        report("HUD+ update + render", () ->
        {
            builder.update(snapshot, f -> true, now);
            return overlay.render(g).width;
        });
        Gson gson = new Gson();
        String once = gson.toJson(engine.qm());
        SavedState copy = gson.fromJson(once, SavedState.class);
        copy.aar();
        System.out.println("PERF save JSON bytes " + once.length()
            + ", identical to the old detached copy: " + once.equals(gson.toJson(copy)));
        report("save snapshot (engine lock)", () -> engine.qm().schemaVersion);
        report("detach round trip", () -> gson.fromJson(gson.toJson(engine.qm()), SavedState.class).schemaVersion);
        report("save snapshot + JSON", () -> gson.toJson(engine.qm()).length());
        SessionRepository repository = new SessionRepository(gson,
            FilepathTestSupport.root(java.nio.file.Files.createTempDirectory("gp-perf")));
        Ei coordinator = new Ei(null, null, repository,
            new OrderedPersistenceWriter(repository, null), engine);
        report("save intent (client thread)", () -> coordinator.qn().expectedBaseRevision);
        // 1.1: the periodic gameplay save reuses closed sessions' JSON; every 10th is full.
        report("quick save intent (client thread)", () -> coordinator.qn(true).expectedBaseRevision);
        System.out.println("PERF quick save identical to one toJson: "
            + coordinator.aiw(null, true).replaceFirst("\"savedAtEpochMillis\":\\d+", "")
                .equals(gson.toJson(engine.qm()).replaceFirst("\"savedAtEpochMillis\":\\d+", "")));
    }

    private static Ac receipt(long at)
    {
        List<Ab> flows;
        Ai type;
        Au action = null;
        switch (RANDOM.nextInt(5))
        {
            case 0:
                type = Ai.LOOT;
                flows = Arrays.asList(new Ab(1_319, "Rune axe", 1L, 7_202, 7_202L),
                    new Ab(560, "Death rune", 46L, 187, 8_602L));
                break;
            case 1:
                type = Ai.CONSUMPTION;
                action = Au.CAST;
                flows = Arrays.asList(new Ab(560, "Death rune", -4L, 187, -748L),
                    new Ab(565, "Blood rune", -2L, 341, -682L), new Ab(555, "Water rune", -6L, 5, -30L));
                break;
            case 2:
                type = Ai.CONSUMPTION;
                action = Au.DRINK;
                flows = Arrays.asList(new Ab(2434, "Prayer potion(4)", -1L, 9_800, -9_800L),
                    new Ab(139, "Prayer potion(3)", 1L, 7_350, 7_350L));
                break;
            case 3:
                type = Ai.CONSUMPTION;
                action = Au.FIRE;
                flows = Collections.singletonList(new Ab(808, "Steel dart", -2L, 4, -8L));
                break;
            default:
                type = Ai.GAIN;
                flows = Collections.singletonList(new Ab(526, "Bones", 1L, 37, 37L));
                break;
        }
        Ac transaction = new Ac(at, null, type,
            type == Ai.LOOT ? Aj.LOOT : Aj.GENERIC, "",
            "Greater Nechryael", true, flows, Bd.CONFIRMED, "perf", null);
        transaction.setActionKind(action);
        return transaction;
    }

    private static void report(String name, LongSupplier work)
    {
        for (int i = 0; i < 20; i++)
        {
            work.getAsLong();
        }
        long[] times = new long[100];
        for (int i = 0; i < times.length; i++)
        {
            long start = System.nanoTime();
            work.getAsLong();
            times[i] = System.nanoTime() - start;
        }
        Arrays.sort(times);
        System.out.printf("PERF %-24s median %7.3f ms  p99 %7.3f ms%n", name, times[50] / 1e6, times[98] / 1e6);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A data / factory reset leaves the profile exactly as a new install: no session, nothing
 * accruing. Only Start or the plugin's genuine-activity start
 * ({@link Am#ait}, when Automatic tracking is on)
 * begins tracking, each exactly once; the passive work around a reset (priming, ticks with
 * unchanged containers, saved-state snapshots, restore) never does.
 */
public class ResetStateLifecycleTest
{
    private static final int OAK_LOGS = 1521;

    private static Am engine(AtomicBoolean autoStart)
    {
        GpManagerConfig config = new GpManagerConfig()
        {
            @Override public boolean autoStartSession() { return autoStart.get(); }
            @Override public int stabilizationTicks() { return 0; }
        };
        return new Am(deltas ->
        {
            List<Ab> flows = new ArrayList<>();
            for (Map.Entry<Integer, Long> e : deltas.entrySet())
            {
                flows.add(new Ab(e.getKey(), "Oak logs", e.getValue(), 40, e.getValue() * 40L));
            }
            return flows;
        }, new TransactionClassifier(), config);
    }

    private static Am resetEngine(AtomicBoolean autoStart)
    {
        Am engine = engine(autoStart);
        engine.rm(1_000L);
        engine.setBaseline(new Cc(new HashMap<>()));
        engine.getActiveSession().kf(Tx.of(1_500L, Ai.GAIN,
            Aj.GENERIC, "Old", true,
            Collections.singletonList(new Ab(OAK_LOGS, "Oak logs", 5L, 40, 200L))), 100);
        engine.agr(2_000L);
        return engine;
    }

    @Test
    public void resetLeavesANewInstall()
    {
        Am engine = resetEngine(new AtomicBoolean(true));
        assertNull("no session until play or Start", engine.getActiveSession());
        assertNull(engine.getGeneralSession());
        assertEquals("no history survives", 0, engine.getHistory().size());
        assertEquals(0L, engine.getMetrics(2_000L).net);
        assertEquals(0L, engine.getMetrics(3_600_000L).elapsedMillis);
        assertFalse("no custom session starts because of reset", engine.wb());
    }

    @Test
    public void startAfterResetBeginsTrackingOnce()
    {
        Am engine = resetEngine(new AtomicBoolean(false));
        engine.togglePause(3_000L);
        assertNotNull("Start creates Free play", engine.getActiveSession());
        assertFalse("and it runs, never born paused", engine.getActiveSession().paused);
        assertEquals("active time starts at Start", 60_000L, engine.getActiveSession().getElapsedMillis(63_000L));
        String id = engine.getActiveSession().getId();
        assertFalse("no second start from the activity path", engine.ait(3_100L));
        assertEquals(id, engine.getActiveSession().getId());
    }

    @Test
    public void genuineActivityStartsTrackingOnceAndThenBooks()
    {
        Am engine = resetEngine(new AtomicBoolean(true));
        assertTrue(engine.ait(3_000L));
        assertFalse("already running: no duplicate start", engine.ait(3_100L));

        engine.setBaseline(new Cc(new HashMap<>()));
        engine.yz();
        Map<Integer, Long> logs = new HashMap<>();
        logs.put(OAK_LOGS, 1L);
        assertNull(engine.adj(new Cc(logs), 3_200L));
        Ac gain = engine.adj(new Cc(logs), 3_800L);
        assertNotNull(gain);
        assertEquals(40L, gain.getNet());
        assertEquals(40L, engine.getMetrics(4_000L).net);
    }

    @Test
    public void passiveResetWorkNeverStartsTracking()
    {
        Am engine = resetEngine(new AtomicBoolean(true));
        engine.lp();
        Cc unchanged = new Cc(new HashMap<>());
        for (int tick = 0; tick < 20; tick++)
        {
            assertNull(engine.adj(unchanged, 2_200L + tick * 600L));
        }
        engine.resume(15_000L, Ed.LIFECYCLE);
        engine.resume(15_000L, Ed.IDLE, Ed.RECOVERY);
        engine.resume(15_000L, Ed.IDLE);
        assertNull("resumes have nothing to resume", engine.getActiveSession());

        SavedState committed = engine.qm();
        assertTrue(committed.getHistory().isEmpty());
        Am reloaded = engine(new AtomicBoolean(true));
        reloaded.restore(new Gson().fromJson(new Gson().toJson(committed), SavedState.class), 16_000L);
        assertNull("a reload of the reset profile is still a new install", reloaded.getActiveSession());
        assertEquals(0L, reloaded.getMetrics(3_600_000L).net);
    }

    @Test
    public void activityStartHonoursAutomaticTracking()
    {
        AtomicBoolean autoStart = new AtomicBoolean(false);
        Am engine = resetEngine(autoStart);
        assertFalse("Automatic tracking off: activity cannot start", engine.ait(3_000L));
        assertNull(engine.getActiveSession());
        autoStart.set(true);
        assertTrue(engine.ait(4_000L));
        assertFalse(engine.ait(4_100L));
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
