    @Test
    public void provenOwnDropRecoveryRestoresExactKnownShareAcrossRestart()
    {
        Harness h = new Harness(155);
        h.gain(LOGS, 5L, 775L, h.now - 60_000L);
        Ac drop = new Ac(h.now - 30_000L, null,
