            new Bj.Snapshot(0, CANCELLED_SELL, LOGS, 60, 0, 100, 0)).orElse(null);
        assertNotNull(cancel);
        restarted.abh(cancel, "Logs", h.now + 1_000L);
        restarted.yz();
        Cc back = new Cc(with(h.inventory, LOGS, 60L));
        for (int i = 0; i < 3; i++)
        {
            restarted.adj(back, h.now + 1_000L + i * 600L);
