public class ItemSplitAccountingTest
{
    @Test
    public void applyItemSplitKeepsPersonalShareAndRecordsUndoableCorrection()
    {
        Ad session = new Ad("Split", 0L);
        long priceCapturedAt = 1_725_000_000_123L;
        Ac loot = Tx.of(
            1_000L,
            Ai.LOOT,
            Aj.LOOT,
            "Loot from Corp",
