        assertTrue(session.akb(5_000L));
        assertEquals(10L, session.metrics(6_000L).net);
        assertEquals(priceCapturedAt, loot.getFlows().get(0).getPriceCapturedAtEpochMillis());
        assertFalse(Dm.xr(loot.getExplanation()));
