import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Owner report 2026-09-28: a potion is drunk a dose at a time, so only the dose is a cost. */
public class SipAccountingTest
{
    private static Ac sips(long quantity, Ah correction)
    {
        Ac sips = new Ac(1_000L, null, Ai.CONSUMPTION,
            Aj.GENERIC, "", "Vorkath", true, Arrays.asList(
                new Ab(2434, "Prayer potion(4)", -quantity, 9_800, -quantity * 9_800L),
                new Ab(139, "Prayer potion(3)", quantity, 7_350, quantity * 7_350L)),
            Bd.LIKELY, "fixture", null);
        sips.setActionKind(Au.DRINK);
        if (correction != null)
        {
            sips.ko(correction, 1_500L);
        }
        return sips;
    }

    @Test
    public void twelveSipsAreTwelveDosesNotTwelvePotionsAndTwelveGains()
    {
        Ad session = new Ad("Vorkath", 0L);
        session.kf(sips(12L, null), 100);
        Bu metrics = session.metrics(2_000L);
        assertEquals("the (3) left over is no gain", 0L, metrics.revenue);
        assertEquals("only the doses drunk are a cost", 12L * 2_450L, metrics.costs);
        assertTrue(metrics.costSplitAvailable);
        assertEquals("a drink is a supply", 12L * 2_450L, metrics.suppliesCosts);
        assertEquals(-12L * 2_450L, metrics.net);
    }

    /** Release pass 2026-09-28: a Grind's highlight names a sip by its potion, not its "(4)". */
    @Test
    public void aSipHighlightReadsAsThePotion()
    {
        assertEquals("Prayer potion", Ba.awm(sips(2L, null)));
    }

    @Test
    public void aCorrectedRowKeepsItsGrossAmounts()
    {
        Ad session = new Ad("Vorkath", 0L);
        session.kf(sips(1L, Ah.COST), 100);
        assertEquals("a Cost correction still costs the gross, as before", 9_800L + 7_350L,
            session.metrics(2_000L).costs);
    }
}

package com.gpmanager;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Owner report 2026-09-28: autocast Ice Barrage read "Cast · 3 rune types" with no icon. */
public class SpellsTest
{
    private static Ab rune(String name, long spent)
    {
        return new Ab(1, name, -spent, 100, -spent * 100L);
    }

    @Test
    public void theOwnersAutocastReadsAsIceBarrage()
    {
        // The owner's receipts: 4 Death, 2 Blood, 6 Water per cast, no Cast click.
        assertEquals("Ice Barrage", Spells.a1(Arrays.asList(rune("Death rune", 4), rune("Blood rune", 2),
            rune("Water rune", 6))));
        assertEquals("two casts in one settle", "Ice Barrage", Spells.a1(Arrays.asList(rune("Death rune", 8),
            rune("Blood rune", 4), rune("Water rune", 12))));
        assertEquals("Blood Barrage", Spells.a1(Arrays.asList(rune("Death rune", 4), rune("Blood rune", 4),
            rune("Soul rune", 1))));
        assertEquals("a steam rune pays water", "Ice Barrage", Spells.a1(Arrays.asList(rune("Death rune", 4),
            rune("Blood rune", 2), rune("Steam rune", 6))));
        assertEquals(-328, Spells.icon("Ice Barrage"));
        assertEquals("no spell, no icon", -1, Spells.icon(""));
    }

    @Test
    public void anAmbiguousOrForeignCostStaysACast()
    {
        // A water staff covers the water, and a smoke staff would make Smoke Barrage cost the same.
        assertNull(Spells.a1(Arrays.asList(rune("Death rune", 4), rune("Blood rune", 2))));
        assertNull("uneven casts", Spells.a1(Arrays.asList(rune("Death rune", 4), rune("Blood rune", 3),
            rune("Water rune", 6))));
        assertNull("a rune the spell never uses", Spells.a1(Arrays.asList(rune("Death rune", 4),
            rune("Blood rune", 2), rune("Water rune", 6), rune("Nature rune", 1))));
        assertNull("not only runes", Spells.a1(Arrays.asList(rune("Death rune", 4), rune("Blood rune", 2),
            new Ab(2, "Steel dart", -1L, 4, -4L))));
    }

    @Test
    public void theTableIsWellFormed()
    {
        Set<String> names = new HashSet<>();
        for (String[] spell : Spells.TABLE)
        {
            assertEquals(Arrays.toString(spell), 3, spell.length);
            assertTrue("unique " + spell[0], names.add(spell[0]));
            assertTrue(Integer.parseInt(spell[1]) > 0);
            boolean nonElemental = false;
            for (String part : spell[2].split(" "))
            {
                String[] kv = part.split(":");
                assertTrue(part, Long.parseLong(kv[0]) > 0L);
                nonElemental |= !Spells.ELEMENTS.contains(" " + kv[1] + " ");
            }
            assertTrue("every spell has a rune a staff cannot cover: " + spell[0], nonElemental);
            // Its own full cost always names itself.
            List<Ab> exact = new java.util.ArrayList<>();
            for (String part : spell[2].split(" "))
            {
                String[] kv = part.split(":");
                exact.add(rune(Character.toUpperCase(kv[1].charAt(0)) + kv[1].substring(1) + " rune", Long.parseLong(kv[0])));
            }
            assertEquals(spell[0], Spells.a1(exact));
        }
    }
}

