package com.gpmanager;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import static org.junit.Assert.assertEquals;

/**
 * Immutable, machine-comparable financial state of one engine at one instant.
 *
 * <p>Every dimension that can be unavailable is fingerprinted as the value <em>and</em> its
 * availability; an unavailable dimension is never rendered as zero. Two fingerprints are
 * compared exactly, integer for integer, so a migration or extraction that moves one gp fails.
 */
public final class FinancialFingerprint
{
    private final String text;

    private FinancialFingerprint(String text)
    {
        this.text = text;
    }

    public String text()
    {
        return text;
    }

    @Override
    public String toString()
    {
        return text;
    }

    /** Exact comparison; the assertion message shows the first differing line. */
    public static void assertFinanciallyIdentical(FinancialFingerprint expected, FinancialFingerprint actual)
    {
        if (expected.text.equals(actual.text))
        {
            return;
        }
        String[] left = expected.text.split("\n");
        String[] right = actual.text.split("\n");
        int limit = Math.min(left.length, right.length);
        for (int index = 0; index < limit; index++)
        {
            if (!left[index].equals(right[index]))
            {
                assertEquals("financial fingerprint drifted at line " + (index + 1)
                    + "\nexpected: " + left[index] + "\nactual:   " + right[index], expected.text, actual.text);
            }
        }
        assertEquals("financial fingerprint length drifted", expected.text, actual.text);
    }

    /**
     * Compares accounting, PvP and archive facts exactly. Non-accounting coin-store, category
     * and PvM analytics lines are excluded from the financial comparison.
     */
    public static FinancialFingerprint of(String text)
    {
        StringBuilder kept = new StringBuilder();
        for (String line : text.replace("\r\n", "\n").split("\n"))
        {
            if (line.startsWith("session ") && line.contains(" category="))
            {
                line = line.substring(0, line.indexOf(" category="));
            }
            String trimmed = line.trim();
            if (!line.startsWith("coinStore")
                && !trimmed.startsWith("pvm "))
            {
                kept.append(line).append('\n');
            }
        }
        return new FinancialFingerprint(kept.toString().trim() + "\n");
    }

    /** Captures the engine's effective correction-aware money, PvP metrics and archives at {@code now}. */
    public static FinancialFingerprint fingerprint(Am engine, long now)
    {
        StringBuilder out = new StringBuilder();
        Map<String, Ad> sessions = new LinkedHashMap<>();
        Ad general = engine.getGeneralSession();
        Ad active = engine.getActiveSession();
        if (general != null) sessions.put(general.getId(), general);
        if (active != null) sessions.put(active.getId(), active);
        for (Ad session : engine.getHistory())
        {
            if (session != null) sessions.put(session.getId(), session);
        }
        List<Ad> ordered = new ArrayList<>(sessions.values());
        ordered.sort(Comparator.comparing(Ad::getId));
        out.append("sessions=").append(ordered.size()).append('\n');
        for (Ad session : ordered)
        {
            boolean isActive = active != null && active.getId().equals(session.getId());
            Bu metrics = session.metrics(now);
            Dt pk = session.ava();
            out.append("session ").append(session.getId())
                .append(" owner=").append(session.getOwnerKind())
                .append(" closed=").append(session.isClosed())
                .append(" active=").append(isActive)
                .append('\n');
            if (metrics == null)
            {
                out.append("  metrics unavailable\n");
            }
            else
            {
                out.append("  accounting revenue=").append(metrics.revenue)
                    .append(" costs=").append(metrics.costs)
                    .append(" net=").append(metrics.net)
                    .append('\n');
                out.append("  costSplit ").append(availability(metrics.costSplitAvailable));
                if (metrics.costSplitAvailable)
                {
                    out.append(" supplies=").append(metrics.suppliesCosts)
                        .append(" loss=").append(metrics.otherCosts);
                }
                out.append('\n');
                out.append("  transactions count=").append(SessionCounts.counted(session))
                    .append(" transfers=").append(SessionCounts.transfers(session))
                    .append('\n');
            }
            if (pk == null)
            {
                out.append("  pvp unavailable\n");
            }
            else
            {
                out.append("  pvp kills=").append(pk.kills)
                    .append(" deaths=").append(pk.deaths)
                    .append(" net=").append(pk.net)
                    .append(" bestKill=").append(pk.bestKill)
                    .append(" worstDeath=").append(pk.largestDeathLoss)
                    .append(" killNet=").append(pk.totalKillNet)
                    .append(" deathLoss=").append(pk.totalDeathLoss)
                    .append(" streak=").append(pk.currentStreak)
                    .append('\n');
            }
            out.append("  retainedRows=").append(session.getTransactions().size())
                .append(" compactedRows=").append(session.compactedTransactionCount)
                .append('\n');
            List<Ac> rows = new ArrayList<>(session.getTransactions());
            rows.sort(Comparator.comparing(Ac::getId));
            for (Ac row : rows)
            {
                out.append("  row ").append(row.getId())
                    .append(" type=").append(row.getType())
                    .append(" counted=").append(row.isCounted())
                    .append(" correction=").append(row.getCorrection())
                    .append(" confidence=").append(row.getConfidence())
                    .append(" revenue=").append(row.getRevenue())
                    .append(" costs=").append(row.getCosts())
                    .append(" net=").append(row.getNet())
                    .append(" encounter=").append(row.getEncounterId())
                    .append('\n');
                for (Ab flow : row.getFlows())
                {
                    out.append("    flow item=").append(flow.itemId)
                        .append(" qty=").append(flow.quantityDelta)
                        .append(" unit=").append(flow.unitPrice)
                        .append(" value=").append(flow.valueDelta)
                        .append(" source=").append(flow.getPriceSource())
                        .append('\n');
                }
            }
            List<Bx> encounters = new ArrayList<>(session.getPkEncounters());
            encounters.sort(Comparator.comparing(Bx::getId));
            for (Bx encounter : encounters)
            {
                out.append("  encounter ").append(encounter.getId())
                    .append(" type=").append(encounter.getType())
                    .append(" at=").append(encounter.timestampEpochMillis)
                    .append(" net=").append(encounter.ur())
                    .append(" loss=").append(encounter.uk())
                    .append('\n');
            }
        }

        return new FinancialFingerprint(out.toString());
    }

    private static String availability(boolean available)
    {
        return available ? "available" : "unavailable";
    }

    static String lower(Object value)
    {
        return String.valueOf(value).toLowerCase(Locale.ROOT);
    }
}

package com.gpmanager;

import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.nio.file.Files;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;

/**
 * A real RuneLite {@link ConfigManager} with no client, session or remote behind it: its two
 * property stores point at empty temp files, so tests exercise the production get/set/unset path
 * in memory without touching {@code ~/.runelite}. Test-only reflection.
 */
public final class IsolatedConfigManager
{
    private IsolatedConfigManager()
    {
    }

    public static ConfigManager create(String rsProfileKey)
    {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        try
        {
            Constructor<ConfigManager> constructor = ConfigManager.class.getDeclaredConstructor(
                String.class, ScheduledExecutorService.class, EventBus.class, Client.class,
                Gson.class, Class.forName("net.runelite.client.config.ConfigClient"),
                Class.forName("net.runelite.client.config.ProfileManager"),
                Class.forName("net.runelite.client.account.SessionManager"));
            constructor.setAccessible(true);
            ConfigManager manager = constructor.newInstance("test", executor, new EventBus(), null,
                new Gson(), null, null, null);
            set(manager, "configProfile", emptyConfigData());
            set(manager, "rsProfileConfigProfile", emptyConfigData());
            if (rsProfileKey != null)
            {
                set(manager, "rsProfileKey", rsProfileKey);
            }
            return manager;
        }
        catch (ReflectiveOperationException | java.io.IOException ex)
        {
            throw new AssertionError("Could not create isolated ConfigManager fixture", ex);
        }
        finally
        {
            executor.shutdown();
        }
    }

    /** Writes every entry into {@code group} as raw strings for an isolated settings fixture. */
    public static ConfigManager seeded(String rsProfileKey, String group, Map<String, String> raw)
    {
        ConfigManager manager = create(rsProfileKey);
        for (Map.Entry<String, String> entry : raw.entrySet())
        {
            manager.setConfiguration(group, entry.getKey(), entry.getValue());
        }
        return manager;
    }

    private static Object emptyConfigData() throws ReflectiveOperationException, java.io.IOException
    {
        Class<?> type = Class.forName("net.runelite.client.config.ConfigData");
        Constructor<?> constructor = type.getDeclaredConstructor(File.class);
        constructor.setAccessible(true);
        File file = Files.createTempFile("gp-manager-config", ".properties").toFile();
        file.deleteOnExit();
        return constructor.newInstance(file);
    }

    private static void set(ConfigManager manager, String field, Object value) throws ReflectiveOperationException
    {
        Field target = ConfigManager.class.getDeclaredField(field);
        target.setAccessible(true);
        target.set(manager, value);
    }
}

package com.gpmanager;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import net.runelite.client.config.ConfigItem;

/**
 * Hand-written JDK Proxy that <em>imitates</em> RuneLite {@code ConfigInvocationHandler}
 * for unit tests: methods without {@link ConfigItem} return {@code null} (primitives then
 * null-unbox), while annotated default methods run their interface bodies.
 *
 * <p><strong>Not</strong> a live {@code ConfigManager}, Guice injection, persisted settings
 * parse, or {@code GpManagerPlugin#startUp} integration test. Never reads or writes real
 * {@code ~/.runelite} settings. A TemporaryFolder-backed ConfigManager smoke remains a
 * follow-up improvement.
 */
public final class RuneLiteStyleConfigProxy
{
    private RuneLiteStyleConfigProxy()
    {
    }

    public static <T> T create(Class<T> configInterface)
    {
        if (configInterface == null || !configInterface.isInterface())
        {
            throw new IllegalArgumentException("configInterface must be an interface");
        }
        Object proxy = Proxy.newProxyInstance(
            configInterface.getClassLoader(),
            new Class<?>[] { configInterface },
            new Handler(configInterface));
        return configInterface.cast(proxy);
    }

    private static final class Handler implements InvocationHandler
    {
        private final Class<?> configInterface;

        private Handler(Class<?> configInterface)
        {
            this.configInterface = configInterface;
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable
        {
            if (method.getDeclaringClass() == Object.class)
            {
                return invokeObject(proxy, method, args);
            }
            if (method.getAnnotation(ConfigItem.class) == null)
            {
                // Same as RuneLite: warn + null; callers of primitives NPE on unbox.
                return null;
            }
            if (!method.isDefault())
            {
                return null;
            }
            return invokeDefault(configInterface, proxy, method, args);
        }
    }

    private static Object invokeDefault(
        Class<?> iface,
        Object proxy,
        Method method,
        Object[] args) throws Throwable
    {
        MethodHandles.Lookup lookup = MethodHandles.privateLookupIn(iface, MethodHandles.lookup());
        MethodHandle handle = lookup.unreflectSpecial(method, iface).bindTo(proxy);
        return handle.invokeWithArguments(args == null ? new Object[0] : args);
    }

    private static Object invokeObject(Object proxy, Method method, Object[] args)
    {
        String name = method.getName();
        if ("toString".equals(name))
        {
            return "RuneLiteStyleConfigProxy(" + proxy.getClass().getInterfaces()[0].getSimpleName() + ")";
        }
        if ("hashCode".equals(name))
        {
            return System.identityHashCode(proxy);
        }
        if ("equals".equals(name))
        {
            return proxy == args[0];
        }
        throw new UnsupportedOperationException(name);
    }
}

package com.gpmanager;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Character idle is presentation-only — must not pause the session or change GP/hr.
 */
public class CharacterIdleGpHrGuardrailTest
{
    @Test
    public void characterIdleDoesNotPauseSessionOrChangeRate()
    {
        Ad session = new Ad("Test", 0L);
        session.kf(
            Tx.of(
                1_000L,
                1_000L,
                Ai.GAIN,
                Aj.GENERIC,
                "",
                true,
                Collections.singletonList(new Ab(526, "Bones", 1, 100, 100L))),
            1);

        Bu before = session.metrics(10_000L);
        CharacterIdleModel idle = new CharacterIdleModel();
        idle.delayMillis = 2_000L;
        assertFalse(idle.tick(false, false, 10_000L));
        assertTrue(idle.tick(false, false, 12_000L));
        assertTrue(idle.characterIdle);

        Bu after = session.metrics(10_000L);
        assertEquals(before.elapsedMillis, after.elapsedMillis);
        assertEquals(before.profitPerHour, after.profitPerHour);
        assertEquals(before.net, after.net);
        assertFalse(session.paused);
    }

    @Test
    public void afkPauseStillFreezesRateAndLabelsAfk()
    {
        Ad session = new Ad("Test", 0L);
        session.kf(
            Tx.of(
                1_000L,
                1_000L,
                Ai.GAIN,
                Aj.GENERIC,
                "",
                true,
                Collections.singletonList(new Ab(526, "Bones", 1, 100, 100L))),
            1);

        session.pause(2_000L, Ed.IDLE);
        Bu atPause = session.metrics(2_000L);
        Bu later = session.metrics(62_000L);
        assertEquals(atPause.elapsedMillis, later.elapsedMillis);
        assertEquals(atPause.profitPerHour, later.profitPerHour);
        assertEquals(Ed.IDLE, session.getPauseReason());
    }
}

package com.gpmanager;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CharacterIdleModelTest
{
    @Test
    public void delayRequiredBeforeIdle()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 5_000L;
        assertFalse(model.tick(false, false, 1_000L));
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, false, 5_999L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 6_000L));
        assertTrue(model.characterIdle);
        assertFalse(model.tick(false, false, 7_000L));
        assertTrue(model.characterIdle);
    }

    @Test
    public void animationOrInteractClearsIdle()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        assertFalse(model.tick(false, false, 1_000L));
        assertTrue(model.tick(false, false, 3_000L));
        assertTrue(model.characterIdle);
        assertFalse(model.tick(true, false, 3_100L));
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, true, 4_000L));
        assertFalse(model.characterIdle);
    }

    @Test
    public void clearResetsState()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        assertFalse(model.tick(false, false, 1_000L));
        assertTrue(model.tick(false, false, 3_000L));
        model.clear();
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, false, 3_500L));
    }

    @Test
    public void busyAndXpPreventIdle()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        assertFalse(model.tick(true, false, 1_000L));
        assertFalse(model.characterIdle);
        assertFalse(model.tick(false, false, 3_000L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 5_000L));
        assertTrue(model.characterIdle);

        model.clear();
        model.abn(10_000L);
        assertFalse(model.tick(false, false, 11_000L));
        assertFalse(model.characterIdle);
        // XP soft-busy lasts for the idle delay after the drop — Idle fires then,
        // without stacking a second full delay.
        assertFalse(model.tick(false, false, 11_999L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 12_000L));
        assertTrue(model.characterIdle);
    }

    @Test
    public void hardBusyStillRequiresFullDelayAfterClear()
    {
        CharacterIdleModel model = new CharacterIdleModel();
        model.delayMillis = 2_000L;
        model.abn(10_000L);
        assertFalse(model.tick(true, false, 10_500L));
        assertFalse(model.tick(false, false, 12_000L));
        assertFalse(model.characterIdle);
        assertTrue(model.tick(false, false, 14_000L));
        assertTrue(model.characterIdle);
    }

}

