import org.junit.Test;

import static com.gpmanager.HudBuilderTest.NOW;
import static com.gpmanager.HudTrayTest.flow;
import static com.gpmanager.HudTrayTest.receipt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/** Owner 1.1: every icon is cropped, fitted to one box and centred; icons can be turned off. */
public class IconFitTest
{
    private static BufferedImage sprite(int x, int y, int w, int h)
    {
        BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(Color.RED);
        g.fillRect(x, y, w, h);
        g.dispose();
        return image;
    }

    @Test
    public void aLargeSpriteIsCroppedScaledDownAndCentred()
    {
        BufferedImage fitted = Kit.fitIcon(sprite(2, 5, 30, 10), Kit.ICON_BOX);
        assertEquals(Kit.ICON_BOX, fitted.getWidth());
        assertEquals(Kit.ICON_BOX, fitted.getHeight());
        assertEquals("30 x 10 scales to 24 x 8, centred", new Rectangle(0, 8, 24, 8), Kit.visible(fitted));
    }

    @Test
    public void aSmallSpriteIsNeverBlownUp()
    {
        BufferedImage fitted = Kit.fitIcon(sprite(10, 12, 4, 6), Kit.ICON_BOX);
        assertEquals(new Rectangle(10, 9, 4, 6), Kit.visible(fitted));
    }

    @Test
    public void iconsOffLeavesTrayRowsWithoutSprites()
    {
        for (boolean show : new boolean[] {true, false})
        {
            GpManagerConfig config = new GpManagerConfig()
            {
                @Override public boolean hudHideWhenIdle() { return false; }
                @Override public boolean showItemIcons() { return show; }
            };
            Cp builder = new Cp(config, (id, quantity) -> sprite(2, 2, 20, 20));
            builder.update(HudBuilderTest.grind(1_000L, null), f -> true, NOW);
            builder.tray().booked(receipt(NOW + 1L, Ai.LOOT, flow(1420, "Iron mace", 1L, 42)), NOW + 1L, false);
            Cb s = builder.update(HudBuilderTest.grind(1_042L, null), f -> true, NOW + 2L);
            if (show) assertNotNull(s.rows.get(0).icon);
            else assertNull("item icons off", s.rows.get(0).icon);
        }
    }
}

package com.gpmanager;

import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.components.materialtabs.MaterialTab;

/** Test-side access to Shell state. */
public final class ShellProbe
{
    private ShellProbe()
    {
    }

    /** Tab labels in order. */
    public static String[] tabLabels(Shell shell)
    {
        String[] labels = new String[Shell.TABS.length];
        for (int i = 0; i < Shell.TABS.length; i++)
        {
            labels[i] = Shell.TABS[i][1];
        }
        return labels;
    }

    /** The selected tab's page id, as the tab strip shows it. */
    public static String selectedTab(Shell shell)
    {
        for (Map.Entry<String, MaterialTab> entry : shell.tabById.entrySet())
        {
            if (entry.getValue().isSelected())
            {
                return entry.getKey();
            }
        }
        return "";
    }

    public static void scrollCurrentToTop(Shell shell)
    {
        JScrollPane pane = shell.scrolls.get(shell.current);
        if (pane != null)
        {
            pane.getVerticalScrollBar().setValue(0);
            shell.scrollMemory.put(shell.current, 0);
        }
    }

    private static final String DEV_FOOTER = "gp-dev-footer";

    /** Dev builds only: a badge row under the notice line (null clears it). Production has no footer. */
    public static void setBadge(Shell shell, @Nullable JComponent badge)
    {
        JPanel footer = footer(shell);
        if (footer == null)
        {
            Component notice = ((BorderLayout) shell.getLayout()).getLayoutComponent(BorderLayout.SOUTH);
            JPanel bottom = new JPanel(new BorderLayout());
            bottom.setName(DEV_FOOTER);
            bottom.setOpaque(false);
            shell.remove(notice);
            bottom.add(notice, BorderLayout.NORTH);
            footer = new JPanel(new BorderLayout());
            footer.setOpaque(false);
            Kit.pad(footer, 2, Kit.GAP, 3, Kit.GAP);
            bottom.add(footer, BorderLayout.SOUTH);
            shell.add(bottom, BorderLayout.SOUTH);
        }
        footer.removeAll();
        if (badge != null)
        {
            footer.add(badge, BorderLayout.WEST);
        }
        footer.setVisible(badge != null);
        shell.revalidate();
    }

    @Nullable
    public static JComponent badge(Shell shell)
    {
        JPanel footer = footer(shell);
        return footer == null || footer.getComponentCount() == 0 ? null : (JComponent) footer.getComponent(0);
    }

    @Nullable
    private static JPanel footer(Shell shell)
    {
        Component south = ((BorderLayout) shell.getLayout()).getLayoutComponent(BorderLayout.SOUTH);
        return south != null && DEV_FOOTER.equals(south.getName())
            ? (JPanel) ((JPanel) south).getComponent(1) : null;
    }

    /** Presses the sheet button with this label, wherever it nests. */
    public static void pressSheet(Shell shell, String label)
    {
        for (JButton button : sheetButtons(shell))
        {
            if (label.equals(button.getText()))
            {
                button.doClick();
                return;
            }
        }
        throw new IllegalArgumentException("no sheet button " + label);
    }

    /** Types into the sheet's text field. */
    public static void typeSheet(Shell shell, String text)
    {
        for (java.awt.Component row : shell.sheet.getComponents())
        {
            if (row instanceof JPanel)
            {
                for (java.awt.Component c : ((JPanel) row).getComponents())
                {
                    if (c instanceof javax.swing.JTextField)
                    {
                        ((javax.swing.JTextField) c).setText(text);
                        return;
                    }
                }
            }
        }
        throw new IllegalArgumentException("no sheet field");
    }

    /** The sheet's buttons, in tree order (rows, pager, choices). */
    public static List<JButton> sheetButtons(Shell shell)
    {
        List<JButton> out = new ArrayList<>();
        collectButtons(shell.sheet, out);
        return out;
    }

    /** The sheet's button texts, in tree order. */
    public static List<String> sheetButtonTexts(Shell shell)
    {
        List<String> out = new ArrayList<>();
        for (JButton button : sheetButtons(shell))
        {
            out.add(button.getText());
        }
        return out;
    }

    /** Presses the first enabled sheet button with this exact text, wherever it nests. */
    public static boolean pressSheetText(Shell shell, String text)
    {
        for (JButton button : sheetButtons(shell))
        {
            if (text.equals(button.getText()) && button.isEnabled())
            {
                button.doClick();
                return true;
            }
        }
        return false;
    }

    private static void collectButtons(Component root, List<JButton> out)
    {
        if (root instanceof JButton)
        {
            out.add((JButton) root);
        }
        if (root instanceof java.awt.Container)
        {
            for (Component child : ((java.awt.Container) root).getComponents())
            {
                collectButtons(child, out);
            }
        }
    }

    /** The sheet's checkbox whose label contains this text, or null. */
    @Nullable
    public static JCheckBox sheetCheckbox(Shell shell, String label)
    {
        for (java.awt.Component row : shell.sheet.getComponents())
        {
            if (row instanceof JPanel)
            {
                for (java.awt.Component c : ((JPanel) row).getComponents())
                {
                    if (c instanceof JCheckBox && ((JCheckBox) c).getText().contains(label))
                    {
                        return (JCheckBox) c;
                    }
                }
            }
        }
        return null;
    }

    public static String sheetTitle(Shell shell)
    {
        return shell.sheetTitle;
    }

    /** The notification text now showing, or "". */
    public static String noticeText(Shell shell)
    {
        return shell.notice.isVisible() ? shell.noticeText.getToolTipText() : "";
    }
}

package com.gpmanager;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

/** Test support: reads kit tables back as text, every page, without widening the plugin's API. */
public final class TableRows
{
    private TableRows()
    {
    }

    /** Rows of every table under {@code root} whose title starts with {@code title}, as "name|qty|value|exact|tip". */
    public static List<String> of(Component root, String title)
    {
        List<String> texts = new ArrayList<>();
        for (Table table : tables(root, title))
        {
            for (Table.Row row : rows(table))
            {
                texts.add(row.name + "|" + row.qty + "|" + row.value + "|" + row.exact + "|" + row.tip);
            }
        }
        return texts;
    }

    /** Row keys of matching tables, every page. */
    public static List<String> keys(Component root, String title)
    {
        List<String> keys = new ArrayList<>();
        for (Table table : tables(root, title))
        {
            for (Table.Row row : rows(table))
            {
                keys.add(row.key);
            }
        }
        return keys;
    }

    /** Runs the open action of the first matching row whose key is {@code key}. */
    public static boolean open(Component root, String title, String key)
    {
        for (Table table : tables(root, title))
        {
            for (Table.Row row : rows(table))
            {
                if (row.key.equals(key) && row.open != null)
                {
                    row.open.run();
                    return true;
                }
            }
        }
        return false;
    }

    /** Row components actually built and visible in every table under {@code root}. */
    public static int visibleRows(Component root)
    {
        int count = 0;
        for (Table table : tables(root, ""))
        {
            if (table.body.isVisible())
            {
                for (Component child : table.body.getComponents())
                {
                    count += child instanceof javax.swing.JLabel ? 0 : 1;
                }
            }
        }
        return count;
    }

    public static List<Table> tables(Component root, String title)
    {
        List<Table> found = new ArrayList<>();
        collect(root, title, found);
        return found;
    }

    public static String title(Table table)
    {
        return ((javax.swing.JLabel) field(table, "title")).getText();
    }

    @SuppressWarnings("unchecked")
    private static List<Table.Row> rows(Table table)
    {
        return (List<Table.Row>) field(table, "rows");
    }

    private static void collect(Component component, String title, List<Table> found)
    {
        if (component instanceof Table && title((Table) component).startsWith(title))
        {
            found.add((Table) component);
        }
        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                collect(child, title, found);
            }
        }
    }

    private static Object field(Table table, String name)
    {
        try
        {
            Field field = Table.class.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(table);
        }
        catch (ReflectiveOperationException e)
        {
            throw new AssertionError(e);
        }
    }
    /** Names of the rows on the page shown now. */
    public static List<String> names(Table table) {
        @SuppressWarnings("unchecked")
        List<Table.Row> drawn = (List<Table.Row>) field(table, "drawn");
        List<String> names = new ArrayList<>();
        for (Table.Row row : drawn == null ? java.util.Collections.<Table.Row>emptyList() : drawn) {
            names.add(row.name);
        }
        return names;
    }

    public static String pageText(Table table) {
        return (page(table) + 1) + "/" + table.pages();
    }

    public static int page(Table table) { return (Integer) field(table, "page"); }

}

package com.gpmanager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TableTest
{
    private static List<Table.Row> rows(int count)
    {
        List<Table.Row> rows = new ArrayList<>();
        for (int i = 0; i < count; i++)
        {
            rows.add(Table.Row.of("k" + i, "Item " + i, "×" + i, "+" + i, Kit.Tone.GAIN));
        }
        return rows;
    }

    @Test
    public void pagesClampAndReset()
    {
        Table table = new Table("GAINS").setRowsPerPage(10).setRows(rows(23));
        assertEquals(3, table.pages());
        assertEquals("1/3", table.pageLabel.getText());

        // Last page, then a shorter list: the page clamps instead of going blank.
        lastPage(table);
        assertEquals(2, TableRows.page(table));
        assertEquals(3, table.body.getComponentCount());
        table.setRows(rows(12));
        assertEquals(1, TableRows.page(table));
        assertEquals(2, table.body.getComponentCount());
        table.avd();
        assertEquals(0, TableRows.page(table));
        assertEquals(10, table.body.getComponentCount());
    }

    private static void lastPage(Table table)
    {
        while (TableRows.page(table) < table.pages() - 1)
        {
            int before = TableRows.page(table);
            clickNext(table);
            assertTrue(TableRows.page(table) > before);
        }
    }

    private static void clickNext(Table table)
    {
        for (java.awt.Component c : table.pageLabel.getParent().getComponents())
        {
            if (c instanceof javax.swing.JButton && "›".equals(((javax.swing.JButton) c).getText()))
            {
                ((javax.swing.JButton) c).doClick();
                return;
            }
