        }
        Ca.Recent grouped = snapshot.recent.stream()
            .filter(row -> row.receipts == 2).findFirst().orElseThrow(AssertionError::new);
        assertEquals(-720L, grouped.value);
        assertEquals("3 rune types \u00b7 \u00d72", LivePage.metaOf(grouped));
