import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Owner 2026-10-01 (F05): the Review pager stays reachable and Decide all names its count. */
public class ReviewBulkPagerTest
{
    private static final long NOW = 1_700_000_000_000L;

    @Test
    public void thePagerStaysReachableAndTheBulkLineNamesItsCount() throws Exception
    {
        Fixture fixture = new Fixture();
        fixture.apply(Ao.Entry.current());

        assertNull("the header pager is not replaced", fixture.page.review.action);
        assertEquals("1/2", fixture.page.review.pageLabel.getText());
        assertTrue(fixture.page.review.next.isEnabled());
        assertEquals("7 of 7", fixture.bulkLabel().getText());
        assertEquals("the bulk target count matches the preview", 7,
            fixture.engine.adu(Cl.GAIN, row -> true, NOW + 20_000L).rowCount());

        fixture.page.review.next.doClick();
        assertEquals("the sixth receipt is reachable", "2/2",
            fixture.page.review.pageLabel.getText());
        assertTrue(fixture.page.review.previous.isEnabled());

        Am.DecideAllPreview one = fixture.engine.adu(Cl.GAIN,
            row -> row.transactionId.equals(fixture.page.data.review.rows.get(0).transactionId),
            NOW + 30_000L);
        assertEquals(1, one.rowCount());
        assertTrue(fixture.engine.kp(one, NOW + 30_000L) >= 0);
        fixture.apply(Ao.Entry.current());
        assertEquals("the count follows a decision", "6 of 6", fixture.bulkLabel().getText());
    }

    @Test
    public void aFilteredBulkLineNamesTheFilteredCount() throws Exception
    {
        Fixture fixture = new Fixture();
        fixture.apply(Ao.Entry.current().withSearch("Alpha"));
        assertEquals("2 of 7", fixture.bulkLabel().getText());
    }

    @Test
    public void aHistoricalScopeHasNeitherBulkLineNorPager() throws Exception
    {
        Fixture fixture = new Fixture();
        String id = fixture.engine.getActiveSession().getId();
        fixture.engine.sx(NOW);
        fixture.apply(Ao.Entry.current().withScope(Ao.Scope.HISTORY, id, "Vorkath"));

        assertNull("read-only keeps its audit hidden", fixture.page.review.extra);
        assertNull(fixture.page.review.action);
    }

    private static final class Fixture
    {
        final Am engine;
        final LedgerPage page;

        Fixture() throws Exception
        {
            engine = new Am(deltas -> Collections.emptyList(), new TransactionClassifier(),
                new GpManagerConfig() {});
            engine.ajl("Vorkath", Cx.GENERAL, NOW - 3_600_000L);
            for (int i = 0; i < 7; i++)
            {
                String name = i < 2 ? "Alpha" : "Bones " + (char) ('A' + i);
                engine.getActiveSession().kf(new Ac(NOW - 3_000_000L + i, null, Ai.GAIN,
                    Aj.GENERIC, "", "Loot", true,
                    Collections.singletonList(new Ab(536, name, 1L, 100, 100L)),
                    Bd.UNCERTAIN, "", null), 500);
            }
            page = onEdt(() -> new LedgerPage(new NoopActions(), id -> null));
        }

        void apply(Ao.Entry entry) throws Exception
        {
            onEdt(() ->
            {
                page.apply(Ao.capture(engine, NOW, entry));
                return null;
            });
        }

        JLabel bulkLabel()
        {
            if (page.review.extra == null)
            {
                return null;
            }
            for (java.awt.Component component : page.review.extra.getComponents())
            {
                if (component instanceof JLabel)
                {
                    return (JLabel) component;
                }
            }
            throw new AssertionError("the bulk line has no count label");
        }
    }

    private static final class NoopActions implements LedgerPage.Actions
    {
        @Override public void openScopeMenu(javax.swing.JComponent anchor) { }
        @Override public void costViewChanged(Ao.Bs view) { }
        @Override public void searchChanged(String text) { }
        @Override public Ao.Ef preview(String id, Ah correction) { return null; }
        @Override public LedgerPage.Ea correct(String id, Ah correction, long revision)
        { return LedgerPage.Ea.REFUSED; }
        @Override public void split(String id, java.util.function.BiConsumer<long[], Ao.Ef> previewed) { }
        @Override public void undoCorrection() { }
        @Override public void decideAll(Cl decision) { }
        @Override public void refresh() { }
    }

    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            return callable.call();
        }
        java.util.concurrent.atomic.AtomicReference<T> value = new java.util.concurrent.atomic.AtomicReference<>();
        java.util.concurrent.atomic.AtomicReference<Throwable> failure =
            new java.util.concurrent.atomic.AtomicReference<>();
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                value.set(callable.call());
            }
            catch (Throwable ex)
            {
                failure.set(ex);
            }
        });
        if (failure.get() != null)
        {
            throw new AssertionError(failure.get());
        }
        return value.get();
    }
}

package com.gpmanager;

import java.time.LocalDate;
import java.time.ZoneId;
import java.util.Collections;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Owner 2026-10-01 (F03): Runs today is whole runs that started today in the profile zone. */
public class RunsTodayScopeTest
{
    @Test
    public void runsTodayIncludesTheCurrentRunAndTodayStartedRunsOnly() throws Exception
    {
        Am engine = engine("UTC");
        ZoneId zone = ZoneId.of("UTC");
        long midnight = LocalDate.of(2026, 3, 7).atStartOfDay(zone).toInstant().toEpochMilli();
        long now = midnight + 12L * 3_600_000L;

        engine.ajl("Overnight", Cx.GENERAL, midnight - 300_000L);
        String overnightId = engine.getActiveSession().getId();
        book(engine, midnight - 299_000L, 1_000L);
        engine.sx(midnight + 600_000L);

        engine.ajl("Morning", Cx.GENERAL, midnight + 900_000L);
        String morningId = engine.getActiveSession().getId();
        book(engine, midnight + 901_000L, 2_000L);
        engine.sx(midnight + 1_800_000L);

        engine.ajl("Live", Cx.GENERAL, midnight - 120_000L);
        book(engine, midnight - 119_000L, 3_000L);

        Ao.Entry entry = Ao.Entry.current().withScope(Ao.Scope.TODAY, null, null);
        List<Ad> sessions = Ao.aig(engine, entry, now);
        assertEquals("whole runs, not calendar slices", 2, sessions.size());
        assertEquals("the current run is included in full even though it started yesterday",
            engine.getActiveSession().getId(), sessions.get(0).getId());
        assertEquals("a run that started today is included", morningId, sessions.get(1).getId());
        assertTrue("the overnight run is out", sessions.stream()
            .noneMatch(session -> overnightId.equals(session.getId())));

        Ao data = Ao.capture(engine, now, entry);
        assertEquals("only whole-run totals: the overnight run's money stays out", 5_000L, data.net);
    }

    @Test
    public void midnightBoundaryHoldsAcrossDstDays() throws Exception
    {
        for (String zoneId : new String[] {"UTC", "America/New_York"})
        {
            Am engine = engine(zoneId);
            ZoneId zone = ZoneId.of(zoneId);
            long midnight = LocalDate.of(2026, 3, 8).atStartOfDay(zone).toInstant().toEpochMilli();
            long now = midnight + 12L * 3_600_000L;

            engine.ajl("JustBefore", Cx.GENERAL, midnight - 1L);
            String beforeId = engine.getActiveSession().getId();
            engine.sx(midnight + 60_000L);

            engine.ajl("AtMidnight", Cx.GENERAL, midnight);

            Ao.Entry entry = Ao.Entry.current().withScope(Ao.Scope.TODAY, null, null);
            List<Ad> sessions = Ao.aig(engine, entry, now);
            assertEquals("only the run started at midnight is today", 1, sessions.size());
            assertEquals(engine.getActiveSession().getId(), sessions.get(0).getId());
            assertTrue(sessions.stream().noneMatch(session -> beforeId.equals(session.getId())));
        }
    }

    @Test
    public void theScopeSaysRunsTodayAndDisclosesItsMembership() throws Exception
    {
        Am engine = engine("UTC");
        long now = System.currentTimeMillis();
        engine.ajl("Live", Cx.GENERAL, now);

        Dp panel = onEdt(() -> new Dp(engine, new GpManagerConfig() {}, null));
        onEdt(() ->
        {
            panel.ledger.apply(Ao.capture(engine, now,
                Ao.Entry.current().withScope(Ao.Scope.TODAY, null, null)));
            return null;
        });

        assertEquals("Runs today ▾", panel.ledger.scope.getText());
        assertTrue("the tooltip names the membership",
            panel.ledger.scope.getToolTipText().contains("runs started today"));
        assertTrue("the note names the membership too",
            containsText(panel.ledger.body, "Runs today"));
    }

    private static boolean containsText(java.awt.Container parent, String needle)
    {
        for (java.awt.Component child : parent.getComponents())
        {
            if (child instanceof JLabel && ((JLabel) child).getText() != null
                && ((JLabel) child).getText().contains(needle))
            {
                return true;
            }
            if (child instanceof java.awt.Container
                && containsText((java.awt.Container) child, needle))
            {
                return true;
            }
        }
        return false;
    }

    private static Ac book(Am engine, long at, long value)
    {
        Ac receipt = new Ac(at, null, Ai.LOOT, Aj.LOOT, "", "Vorkath", true,
            Collections.singletonList(new Ab(536, "Dragon bones", 1L, (int) value, value)),
            Bd.CONFIRMED, "fixture", null);
        engine.getActiveSession().kf(receipt, 2_000);
        return receipt;
    }

    private static Am engine(String zoneId)
    {
        Am engine = new Am(deltas -> Collections.emptyList(), new TransactionClassifier(),
            new GpManagerConfig() {});
        engine.profileTimeZoneId = zoneId;
        return engine;
    }

    @SuppressWarnings("unchecked")
    private static <T> T onEdt(java.util.concurrent.Callable<T> callable) throws Exception
    {
        Object[] result = new Object[1];
        SwingUtilities.invokeAndWait(() ->
        {
            try
            {
                result[0] = callable.call();
            }
            catch (Exception ex)
            {
                throw new RuntimeException(ex);
            }
        });
        return (T) result[0];
    }
}

